using System;
using TMPro;
using UnityEngine;

namespace LightInDark.UI.Window;

/// <summary>
/// Widget 在容器中的对齐方式
/// </summary>
[Flags]
public enum GUIAlignment
{
    Center = 0,
    Left = 1,
    Right = 2,
    Bottom = 4,
    Top = 8,
    TopLeft = Left | Top,
    TopRight = Right | Top,
    BottomLeft = Left | Bottom,
    BottomRight = Right | Bottom,
}

/// <summary>
/// GUI 尺寸结构
/// </summary>
public struct GUISize
{
    public float Width;
    public float Height;

    public GUISize(float width, float height)
    {
        Width = width;
        Height = height;
    }

    public static GUISize Zero => new(0f, 0f);
    public Vector2 ToVector2() => new(Width, Height);
}

/// <summary>
/// 文本样式
/// </summary>
public class TextStyle
{
    public float FontSize = 2f;
    public Color? TextColor;
    public TextAlignmentOptions Alignment = TextAlignmentOptions.Center;
    public FontStyles Style = FontStyles.Normal;
    public bool EnableWordWrapping = false;

    public static TextStyle Default => new();
    public static TextStyle Title => new() { FontSize = 3f, Style = FontStyles.Bold };
    public static TextStyle Bold => new() { Style = FontStyles.Bold };
    public static TextStyle Small => new() { FontSize = 1.5f };
    public static TextStyle Header => new() { FontSize = 2.5f, Style = FontStyles.Bold, Alignment = TextAlignmentOptions.Left };
}

/// <summary>
/// GUI Widget 基类，所有可显示的 GUI 元素均继承自此
/// </summary>
public abstract class GUIWidget
{
    /// <summary>Widget 在容器中的对齐方式</summary>
    public GUIAlignment Alignment { get; protected set; } = GUIAlignment.Center;

    /// <summary>
    /// 实例化 Widget 为 GameObject
    /// </summary>
    /// <param name="available">可用空间</param>
    /// <param name="actualSize">实际占用的尺寸</param>
    /// <returns>创建的 GameObject，若为不可见的 Widget 可返回 null</returns>
    public abstract GameObject? Instantiate(GUISize available, out GUISize actualSize);
}

/// <summary>
/// GUI 屏幕接口，负责承载和显示 Widget
/// </summary>
public interface IGUIScreen
{
    Transform Transform { get; }
    void SetWidget(GUIWidget? widget, out GUISize actualSize);
}

/// <summary>
/// 可点击元素，封装 PassiveButton
/// </summary>
public class GUIClickable
{
    internal PassiveButton? Button { get; init; }
    internal GUIClickable(PassiveButton? button = null) => Button = button;
}

/// <summary>
/// 点击回调委托
/// </summary>
public delegate void GUIClickAction(GUIClickable clickable);

/// <summary>
/// GUI 工厂接口，提供创建各类 Widget 的方法
/// </summary>
public interface IGUI
{
    /// <summary>空 Widget</summary>
    GUIWidget Empty { get; }

    /// <summary>文本 Widget</summary>
    GUIWidget Text(GUIAlignment alignment, string text, TextStyle? style = null);

    /// <summary>按钮 Widget</summary>
    GUIWidget Button(
        GUIAlignment alignment,
        string text,
        GUIClickAction onClick,
        TextStyle? style = null,
        Color? color = null,
        Color? selectedColor = null
    );

    /// <summary>图片 Widget</summary>
    GUIWidget Image(GUIAlignment alignment, Sprite sprite, GUISize size);

    /// <summary>纵向排列容器</summary>
    GUIWidget VerticalHolder(GUIAlignment alignment, params GUIWidget?[] widgets);

    /// <summary>横向排列容器</summary>
    GUIWidget HorizontalHolder(GUIAlignment alignment, params GUIWidget?[] widgets);

    /// <summary>留白 Widget</summary>
    GUIWidget Margin(float? horizontal = null, float? vertical = null);
}

using TMPro;
using UnityEngine;
using Object = UnityEngine.Object;

namespace LightInDark.UI.Window;

/// <summary>
/// Among Us 原生资源的缓存，延迟加载
/// </summary>
public static class VanillaAsset
{
    private static Sprite? _popUpBackSprite;
    private static Sprite? _textButtonSprite;
    private static Sprite? _fullScreenSprite;
    private static TextMeshPro? _textPrefab;
    private static bool _triedInit;

    /// <summary>弹窗背景 Sprite</summary>
    public static Sprite PopUpBackSprite => TryGet(ref _popUpBackSprite);

    /// <summary>按钮背景 Sprite</summary>
    public static Sprite TextButtonSprite => TryGet(ref _textButtonSprite);

    /// <summary>全屏遮罩 Sprite</summary>
    public static Sprite FullScreenSprite => TryGet(ref _fullScreenSprite);

    /// <summary>标准文本预制体</summary>
    public static TextMeshPro? TextPrefab
    {
        get
        {
            EnsureLoaded();
            return _textPrefab;
        }
    }

    private static Sprite? _whiteSprite;

    /// <summary>始终可用的白色 Sprite</summary>
    public static Sprite WhiteSprite
    {
        get
        {
            if (_whiteSprite != null) return _whiteSprite;
            var tex = Texture2D.whiteTexture;
            _whiteSprite = Sprite.Create(tex, new Rect(0, 0, tex.width, tex.height), new Vector2(0.5f, 0.5f), 100f);
            return _whiteSprite;
        }
    }

    /// <summary>获取可用的按钮背景 Sprite</summary>
    public static Sprite GetButtonSprite()
    {
        EnsureLoaded();
        return _textButtonSprite ?? WhiteSprite;
    }

    /// <summary>获取可用的窗口背景 Sprite</summary>
    public static Sprite GetWindowSprite()
    {
        EnsureLoaded();
        return _popUpBackSprite ?? WhiteSprite;
    }

    /// <summary>获取可用的全屏遮罩 Sprite</summary>
    public static Sprite GetFullScreenSprite()
    {
        EnsureLoaded();
        return _fullScreenSprite ?? WhiteSprite;
    }

    private static Sprite TryGet(ref Sprite? field)
    {
        EnsureLoaded();
        return field ?? WhiteSprite;
    }

    private static void EnsureLoaded()
    {
        if (_triedInit) return;
        _triedInit = true;

        try
        {
            var twitch = TwitchManager.Instance;
            if (twitch == null) return;
            var popUp = twitch.transform.GetChild(0);

            _fullScreenSprite = popUp.GetChild(0).GetComponent<SpriteRenderer>().sprite;
            _textButtonSprite = popUp.GetChild(2).GetComponent<SpriteRenderer>().sprite;
            _popUpBackSprite = popUp.GetChild(3).GetComponent<SpriteRenderer>().sprite;

            _textPrefab = Object.Instantiate(popUp.GetChild(1).GetComponent<TextMeshPro>(), null);
            _textPrefab.gameObject.hideFlags = HideFlags.HideAndDontSave;
            Object.DontDestroyOnLoad(_textPrefab.gameObject);
        }
        catch
        {
            // TwitchManager 未就绪，降级到白色 Sprite
        }
    }

    /// <summary>创建一个可用的 TextMeshPro 文本组件</summary>
    public static TextMeshPro CreateText(GameObject parent)
    {
        TextMeshPro tmp;

        if (_textPrefab != null)
        {
            tmp = Object.Instantiate(_textPrefab, parent.transform, false);
        }
        else
        {
            EnsureLoaded();
            if (_textPrefab != null)
            {
                tmp = Object.Instantiate(_textPrefab, parent.transform, false);
            }
            else
            {
                // 最终降级：直接创建组件并设置默认字体
                var obj = new GameObject("Text");
                obj.layer = LayerMask.NameToLayer("UI");
                obj.transform.SetParent(parent.transform, false);
                tmp = obj.AddComponent<TextMeshPro>();
                var defaultFont = TMP_Settings.defaultFontAsset;
                if (defaultFont != null)
                {
                    tmp.font = defaultFont;
                    tmp.fontSharedMaterial = defaultFont.material;
                }
            }
        }

        return tmp;
    }
}

using System.Collections.Generic;
using TMPro;
using UnityEngine;
using UnityEngine.Events;
using UnityEngine.UI;
using Object = UnityEngine.Object;

namespace LightInDark.UI.Window;

/// <summary>
/// 空 Widget，不创建任何可见对象
/// </summary>
public class EmptyWidget : GUIWidget
{
    public override GameObject? Instantiate(GUISize available, out GUISize actualSize)
    {
        actualSize = GUISize.Zero;
        return null;
    }
}

/// <summary>
/// 文本 Widget
/// </summary>
public class TextWidget : GUIWidget
{
    private readonly string _text;
    private readonly TextStyle _style;

    public TextWidget(GUIAlignment alignment, string text, TextStyle? style = null)
    {
        Alignment = alignment;
        _text = text;
        _style = style ?? TextStyle.Default;
    }

    public override GameObject? Instantiate(GUISize available, out GUISize actualSize)
    {
        var obj = new GameObject("Text");
        obj.layer = LayerMask.NameToLayer("UI");

        var tmp = VanillaAsset.CreateText(obj);
        tmp.text = _text;
        tmp.fontSize = _style.FontSize;
        tmp.alignment = _style.Alignment;
        tmp.fontStyle = _style.Style;
        tmp.enableWordWrapping = _style.EnableWordWrapping;
        tmp.color = _style.TextColor?.ToUnityColor() ?? UColor.white;
        tmp.ForceMeshUpdate();

        actualSize = new GUISize(tmp.preferredWidth, tmp.preferredHeight);
        return obj;
    }
}

/// <summary>
/// 按钮 Widget
/// </summary>
public class ButtonWidget : GUIWidget
{
    private readonly string _text;
    private readonly GUIClickAction _onClick;
    private readonly TextStyle _style;
    private readonly UColor _color;
    private readonly UColor _selectedColor;
    private readonly float _margin;

    public ButtonWidget(
        GUIAlignment alignment,
        string text,
        GUIClickAction onClick,
        TextStyle? style = null,
        Color? color = null,
        Color? selectedColor = null,
        float margin = 0.26f
    )
    {
        Alignment = alignment;
        _text = text;
        _onClick = onClick;
        _style = style ?? TextStyle.Default;
        _color = color?.ToUnityColor() ?? new UColor(0.5f, 0.5f, 0.5f, 1f);
        _selectedColor = selectedColor?.ToUnityColor() ?? new UColor(0.7f, 0.7f, 0.7f, 1f);
        _margin = margin;
    }

    public override GameObject? Instantiate(GUISize available, out GUISize actualSize)
    {
        var obj = new GameObject("Button");
        obj.layer = LayerMask.NameToLayer("UI");

        // 先创建文本测量尺寸
        var textObj = new GameObject("Text");
        textObj.layer = LayerMask.NameToLayer("UI");
        textObj.transform.SetParent(obj.transform, false);

        var tmp = VanillaAsset.CreateText(textObj);
        tmp.text = _text;
        tmp.fontSize = _style.FontSize;
        tmp.alignment = TextAlignmentOptions.Center;
        tmp.fontStyle = _style.Style;
        tmp.color = _style.TextColor?.ToUnityColor() ?? UColor.white;
        tmp.ForceMeshUpdate();

        float textW = tmp.preferredWidth;
        float textH = tmp.preferredHeight;
        float btnW = textW + _margin * 2f;
        float btnH = textH + _margin * 2f;

        // 背景 SpriteRenderer
        var renderer = obj.AddComponent<SpriteRenderer>();
        renderer.sprite = VanillaAsset.GetButtonSprite();
        renderer.drawMode = SpriteDrawMode.Sliced;
        renderer.size = new Vector2(btnW, btnH);
        renderer.color = _color;
        renderer.sortingOrder = 52;

        // 碰撞体
        var collider = obj.AddComponent<BoxCollider2D>();
        collider.size = new Vector2(btnW, btnH);

        // 文本居中
        textObj.transform.localPosition = Vector3.zero;

        // PassiveButton 交互
        var button = obj.AddComponent<PassiveButton>();
        button.OnMouseOver = new UnityEvent();
        button.OnMouseOut = new UnityEvent();
        button.OnClick = new Button.ButtonClickedEvent();

        var clickable = new GUIClickable(button);
        button.OnClick.AddListener((UnityAction)(() => _onClick?.Invoke(clickable)));
        button.OnMouseOver.AddListener((UnityAction)(() => { renderer.color = _selectedColor; }));
        button.OnMouseOut.AddListener((UnityAction)(() => { renderer.color = _color; }));

        actualSize = new GUISize(btnW, btnH);
        return obj;
    }
}

/// <summary>
/// 图片 Widget
/// </summary>
public class ImageWidget : GUIWidget
{
    private readonly Sprite _sprite;
    private readonly GUISize _size;

    public ImageWidget(GUIAlignment alignment, Sprite sprite, GUISize size)
    {
        Alignment = alignment;
        _sprite = sprite;
        _size = size;
    }

    public override GameObject? Instantiate(GUISize available, out GUISize actualSize)
    {
        var obj = new GameObject("Image");
        obj.layer = LayerMask.NameToLayer("UI");

        var renderer = obj.AddComponent<SpriteRenderer>();
        renderer.sprite = _sprite;
        renderer.drawMode = SpriteDrawMode.Sliced;
        renderer.size = _size.ToVector2();
        renderer.sortingOrder = 52;

        actualSize = _size;
        return obj;
    }
}

/// <summary>
/// 纵向排列容器
/// </summary>
public class VerticalHolderWidget : GUIWidget
{
    private readonly GUIWidget?[] _widgets;

    public VerticalHolderWidget(GUIAlignment alignment, params GUIWidget?[] widgets)
    {
        Alignment = alignment;
        _widgets = widgets;
    }

    public override GameObject? Instantiate(GUISize available, out GUISize actualSize)
    {
        var obj = new GameObject("VerticalHolder");
        obj.layer = LayerMask.NameToLayer("UI");

        float totalHeight = 0f;
        float maxWidth = 0f;
        var results = new List<(GameObject? go, GUISize size)>();

        foreach (var widget in _widgets)
        {
            if (widget == null) continue;
            var childObj = widget.Instantiate(available, out var childSize);
            results.Add((childObj, childSize));
            totalHeight += childSize.Height;
            if (childSize.Width > maxWidth) maxWidth = childSize.Width;
        }

        // 从上到下排列
        float y = totalHeight * 0.5f;
        foreach (var (childObj, childSize) in results)
        {
            y -= childSize.Height * 0.5f;

            if (childObj != null)
            {
                childObj.transform.SetParent(obj.transform, false);

                float x = 0f;
                if (Alignment.HasFlag(GUIAlignment.Left))
                    x = -maxWidth * 0.5f + childSize.Width * 0.5f;
                else if (Alignment.HasFlag(GUIAlignment.Right))
                    x = maxWidth * 0.5f - childSize.Width * 0.5f;

                childObj.transform.localPosition = new Vector3(x, y, 0f);
            }

            y -= childSize.Height * 0.5f;
        }

        actualSize = new GUISize(maxWidth, totalHeight);
        return obj;
    }
}

/// <summary>
/// 横向排列容器
/// </summary>
public class HorizontalHolderWidget : GUIWidget
{
    private readonly GUIWidget?[] _widgets;

    public HorizontalHolderWidget(GUIAlignment alignment, params GUIWidget?[] widgets)
    {
        Alignment = alignment;
        _widgets = widgets;
    }

    public override GameObject? Instantiate(GUISize available, out GUISize actualSize)
    {
        var obj = new GameObject("HorizontalHolder");
        obj.layer = LayerMask.NameToLayer("UI");

        float totalWidth = 0f;
        float maxHeight = 0f;
        var results = new List<(GameObject? go, GUISize size)>();

        foreach (var widget in _widgets)
        {
            if (widget == null) continue;
            var childObj = widget.Instantiate(available, out var childSize);
            results.Add((childObj, childSize));
            totalWidth += childSize.Width;
            if (childSize.Height > maxHeight) maxHeight = childSize.Height;
        }

        // 从左到右排列
        float x = -totalWidth * 0.5f;
        foreach (var (childObj, childSize) in results)
        {
            x += childSize.Width * 0.5f;

            if (childObj != null)
            {
                childObj.transform.SetParent(obj.transform, false);

                float y = 0f;
                if (Alignment.HasFlag(GUIAlignment.Bottom))
                    y = -maxHeight * 0.5f + childSize.Height * 0.5f;
                else if (Alignment.HasFlag(GUIAlignment.Top))
                    y = maxHeight * 0.5f - childSize.Height * 0.5f;

                childObj.transform.localPosition = new Vector3(x, y, 0f);
            }

            x += childSize.Width * 0.5f;
        }

        actualSize = new GUISize(totalWidth, maxHeight);
        return obj;
    }
}

/// <summary>
/// 留白 Widget，仅占用空间不创建可见对象
/// </summary>
public class MarginWidget : GUIWidget
{
    private readonly GUISize _size;

    public MarginWidget(float? horizontal = null, float? vertical = null)
    {
        _size = new GUISize(horizontal ?? 0f, vertical ?? 0f);
    }

    public override GameObject? Instantiate(GUISize available, out GUISize actualSize)
    {
        actualSize = _size;
        return null;
    }
}

using LightInDark.Core;
using UnityEngine;
using UnityEngine.Events;
using UnityEngine.UI;
using Object = UnityEngine.Object;

namespace LightInDark.UI.Window;

/// <summary>
/// GUI 屏幕，承载 Widget 的显示。
/// 已通过 ClassInjector 注册为 Il2Cpp 类型。
/// </summary>
public class MetaScreen : MonoBehaviour, IGUIScreen
{
    private GameObject? _root;
    private GameObject? _background;
    private GameObject? _closeButton;
    private GameObject? _blackScreen;

    /// <summary>窗口内边距</summary>
    private const float WindowPadding = 0.3f;

    Transform IGUIScreen.Transform => transform;

    /// <summary>
    /// 生成一个完整的窗口
    /// </summary>
    /// <param name="size">窗口内容区域大小</param>
    /// <param name="parent">父级 Transform</param>
    /// <param name="localPosition">窗口位置</param>
    /// <param name="withCloseButton">是否显示关闭按钮</param>
    /// <param name="withBlackScreen">是否显示半透明黑色遮罩</param>
    public static MetaScreen GenerateWindow(
        Vector2 size,
        Transform parent,
        Vector3 localPosition,
        bool withCloseButton = true,
        bool withBlackScreen = true)
    {
        // 根节点
        var root = new GameObject("MetaWindow");
        root.layer = LayerMask.NameToLayer("UI");
        root.transform.SetParent(parent, false);
        root.transform.localPosition = localPosition;

        MetaScreen screen;

        // 黑色遮罩
        GameObject? blackScreen = null;
        if (withBlackScreen)
        {
            blackScreen = new GameObject("BlackScreen");
            blackScreen.layer = LayerMask.NameToLayer("UI");
            blackScreen.transform.SetParent(root.transform, false);
            blackScreen.transform.localPosition = new Vector3(0f, 0f, 1f);
            var blackRenderer = blackScreen.AddComponent<SpriteRenderer>();
            blackRenderer.sprite = VanillaAsset.GetFullScreenSprite();
            blackRenderer.drawMode = SpriteDrawMode.Sliced;
            blackRenderer.size = new Vector2(30f, 30f);
            blackRenderer.color = new UColor(0f, 0f, 0f, 0.5f);
            blackRenderer.sortingOrder = 50;
        }

        // 窗口背景
        var totalW = size.x + WindowPadding * 2f;
        var totalH = size.y + WindowPadding * 2f;
        var bgObj = new GameObject("WindowBackground");
        bgObj.layer = LayerMask.NameToLayer("UI");
        bgObj.transform.SetParent(root.transform, false);
        bgObj.transform.localPosition = Vector3.zero;
        var bgRenderer = bgObj.AddComponent<SpriteRenderer>();
        bgRenderer.sprite = VanillaAsset.GetWindowSprite();
        bgRenderer.drawMode = SpriteDrawMode.Sliced;
        bgRenderer.size = new Vector2(totalW, totalH);
        bgRenderer.color = UColor.white;
        bgRenderer.sortingOrder = 51;

        // 内容屏幕
        var screenObj = new GameObject("Screen");
        screenObj.layer = LayerMask.NameToLayer("UI");
        screenObj.transform.SetParent(bgObj.transform, false);
        screenObj.transform.localPosition = new Vector3(0f, 0f, -1f);
        screen = screenObj.AddComponent<MetaScreen>();
        screen._root = root;
        screen._background = bgObj;
        screen._blackScreen = blackScreen;

        // 关闭按钮
        if (withCloseButton)
        {
            screen._closeButton = CreateCloseButton(root.transform, new Vector3(totalW * 0.5f - 0.2f, totalH * 0.5f - 0.2f, -2f), screen);
        }

        return screen;
    }

    /// <summary>
    /// 生成一个透明窗口（无背景，无遮罩）
    /// </summary>
    public static MetaScreen GenerateBlankWindow(Vector2 size, Transform parent, Vector3 localPosition)
    {
        var root = new GameObject("MetaWindow");
        root.layer = LayerMask.NameToLayer("UI");
        root.transform.SetParent(parent, false);
        root.transform.localPosition = localPosition;

        var screenObj = new GameObject("Screen");
        screenObj.layer = LayerMask.NameToLayer("UI");
        screenObj.transform.SetParent(root.transform, false);
        screenObj.transform.localPosition = Vector3.zero;
        var screen = screenObj.AddComponent<MetaScreen>();
        screen._root = root;

        return screen;
    }

    /// <summary>
    /// 设置屏幕上显示的 Widget
    /// </summary>
    public void SetWidget(GUIWidget? widget, out GUISize actualSize)
    {
        // 清除已有内容
        for (int i = transform.childCount - 1; i >= 0; i--)
        {
            Object.Destroy(transform.GetChild(i).gameObject);
        }

        if (widget == null)
        {
            actualSize = GUISize.Zero;
            return;
        }

        var obj = widget.Instantiate(new GUISize(100f, 100f), out actualSize);
        if (obj != null)
        {
            obj.transform.SetParent(transform, false);
            obj.transform.localPosition = Vector3.zero;
        }
    }

    /// <summary>
    /// 关闭并销毁窗口
    /// </summary>
    public void Close()
    {
        if (_root != null)
        {
            Object.Destroy(_root);
            _root = null;
        }
    }

    void OnDestroy()
    {
        if (_root != null)
        {
            Object.Destroy(_root);
            _root = null;
        }
    }

    /// <summary>
    /// 创建关闭按钮
    /// </summary>
    private static GameObject CreateCloseButton(Transform parent, Vector3 localPos, MetaScreen screen)
    {
        var obj = new GameObject("CloseButton");
        obj.layer = LayerMask.NameToLayer("UI");
        obj.transform.SetParent(parent, false);
        obj.transform.localPosition = localPos;

        var btnSize = 0.4f;

        var renderer = obj.AddComponent<SpriteRenderer>();
        renderer.sprite = VanillaAsset.GetButtonSprite();
        renderer.drawMode = SpriteDrawMode.Sliced;
        renderer.size = new Vector2(btnSize, btnSize);
        renderer.color = new UColor(0.8f, 0.2f, 0.2f, 1f);
        renderer.sortingOrder = 53;

        var collider = obj.AddComponent<BoxCollider2D>();
        collider.size = new Vector2(btnSize, btnSize);

        // "X" 文本
        var textObj = new GameObject("Text");
        textObj.layer = LayerMask.NameToLayer("UI");
        textObj.transform.SetParent(obj.transform, false);
        textObj.transform.localPosition = Vector3.zero;
        var tmp = VanillaAsset.CreateText(textObj);
        tmp.text = "X";
        tmp.fontSize = 2f;
        tmp.alignment = TMPro.TextAlignmentOptions.Center;
        tmp.color = UColor.white;
        tmp.ForceMeshUpdate();

        var button = obj.AddComponent<PassiveButton>();
        button.OnMouseOver = new UnityEvent();
        button.OnMouseOut = new UnityEvent();
        button.OnClick = new Button.ButtonClickedEvent();
        button.OnClick.AddListener((UnityAction)(() => screen.Close()));
        button.OnMouseOver.AddListener((UnityAction)(() => { renderer.color = new UColor(1f, 0.4f, 0.4f, 1f); }));
        button.OnMouseOut.AddListener((UnityAction)(() => { renderer.color = new UColor(0.8f, 0.2f, 0.2f, 1f); }));

        return obj;
    }

    /// <summary>
    /// 快捷创建一个简单的文本窗口（兼容现有调用）
    /// </summary>
    public static MetaScreen CreateWindow(string text)
    {
        var parent = HudManager.Instance != null ? HudManager.Instance.transform : null;
        if (parent == null)
        {
            LightLogger.LogWarning("[MetaScreen] HudManager 未就绪，无法创建窗口");
            return null!;
        }

        var gui = LIDGUI.Instance;
        var content = gui.VerticalHolder(
            GUIAlignment.Center,
            gui.Text(GUIAlignment.Center, text, TextStyle.Default),
            gui.Margin(vertical: 0.3f),
            gui.Button(GUIAlignment.Center, "关闭", _ => { }, TextStyle.Default)
        );

        var screen = GenerateWindow(
            new Vector2(4f, 1.5f),
            parent,
            Vector3.zero,
            withCloseButton: true,
            withBlackScreen: true
        );

        // 绑定关闭按钮
        screen.SetWidget(content, out _);

        // 重新绑定关闭按钮的点击事件到真正的 Close
        // (GenerateWindow 已创建关闭按钮并绑定 Close)
        return screen;
    }

    /// <summary>
    /// 快捷创建一个带标题和内容的窗口
    /// </summary>
    public static MetaScreen CreateWindow(string title, GUIWidget content)
    {
