/// <summary>
/// GUI 尺寸，基于 Vector2
/// </summary>
public struct GUISize
{
    public float Width;
    public float Height;

    public GUISize(float width, float height)
    {
        Width = width;
        Height = height;
    }

    public static GUISize Zero => new(0f, 0f);
    public Vector2 ToVector2() => new(Width, Height);

    public static implicit operator Vector2(GUISize s) => new(s.Width, s.Height);
    public static implicit operator GUISize(Vector2 v) => new(v.x, v.y);
}

/// <summary>
/// 模糊尺寸（可只指定宽或高，另一个自适应）
/// </summary>
public struct FuzzySize
{
    public float? Width;
    public float? Height;

    public FuzzySize(float? width, float? height)
    {
        Width = width;
        Height = height;
    }

    public static FuzzySize Empty => new(null, null);
}

/// <summary>
/// 文本样式
/// </summary>
public class TextStyle
{
    public float FontSize = 2f;
    public Color? TextColor;
    public TextAlignmentOptions Alignment = TextAlignmentOptions.Center;
    public FontStyles Style = FontStyles.Normal;
    public bool EnableWordWrapping = false;
    public TMP_FontAsset? FontAsset;

    public static TextStyle Default => new();
    public static TextStyle Title => new() { FontSize = 3f, Style = FontStyles.Bold };
    public static TextStyle Bold => new() { Style = FontStyles.Bold };
    public static TextStyle Small => new() { FontSize = 1.5f };
    public static TextStyle Header => new() { FontSize = 2.5f, Style = FontStyles.Bold, Alignment = TextAlignmentOptions.Left };
}

