using TMPro;
using Twitch;
using UnityEngine;
using UnityEngine.UI;
using Object = UnityEngine.Object;

namespace LightInDark.UI.Window;

/// <summary>
/// Among Us 原生资源的延迟缓存。
/// 提供 UnityEngine.UI.Image 和 TextMeshProUGUI 的创建辅助方法。
/// 用户可自定义所有材质。
/// </summary>
public static class VanillaAsset
{
    private static Sprite? _popUpBackSprite;
    private static Sprite? _textButtonSprite;
    private static Sprite? _fullScreenSprite;
    private static TextMeshProUGUI? _textPrefabUGUI;
    private static bool _triedInit;

    /// <summary>弹窗背景 Sprite</summary>
    public static Sprite PopUpBackSprite => TryGet(ref _popUpBackSprite);

    /// <summary>按钮背景 Sprite</summary>
    public static Sprite TextButtonSprite => TryGet(ref _textButtonSprite);

    /// <summary>全屏遮罩 Sprite</summary>
    public static Sprite FullScreenSprite => TryGet(ref _fullScreenSprite);

    private static Sprite? _whiteSprite;

    /// <summary>始终可用的白色 Sprite</summary>
    public static Sprite WhiteSprite
    {
        get
        {
            if (_whiteSprite != null) return _whiteSprite;
            var tex = Texture2D.whiteTexture;
            _whiteSprite = Sprite.Create(tex, new Rect(0, 0, tex.width, tex.height), new Vector2(0.5f, 0.5f), 100f);
            return _whiteSprite;
        }
    }

    /// <summary>获取可用的按钮背景 Sprite</summary>
    public static Sprite GetButtonSprite()
    {
        EnsureLoaded();
        return _textButtonSprite ?? WhiteSprite;
    }

    /// <summary>获取可用的窗口背景 Sprite</summary>
    public static Sprite GetWindowSprite()
    {
        EnsureLoaded();
        return _popUpBackSprite ?? WhiteSprite;
    }

    /// <summary>获取可用的全屏遮罩 Sprite</summary>
    public static Sprite GetFullScreenSprite()
    {
        EnsureLoaded();
        return _fullScreenSprite ?? WhiteSprite;
    }

    private static Sprite TryGet(ref Sprite? field)
    {
        EnsureLoaded();
        return field ?? WhiteSprite;
    }

    private static void EnsureLoaded()
    {
        if (_triedInit) return;
        _triedInit = true;

        try
        {
            var twitch = TwitchManager.Instance;
            if (twitch == null) return;
            var popUp = twitch.transform.GetChild(0);

            _fullScreenSprite = popUp.GetChild(0).GetComponent<SpriteRenderer>().sprite;
            _textButtonSprite = popUp.GetChild(2).GetComponent<SpriteRenderer>().sprite;
            _popUpBackSprite = popUp.GetChild(3).GetComponent<SpriteRenderer>().sprite;
        }
        catch
        {
            // TwitchManager 未就绪，降级到白色 Sprite
        }
    }

    /// <summary>
    /// 创建一个 UnityEngine.UI.Image 组件
    /// </summary>
    public static Image CreateImage(GameObject parent, Sprite? sprite = null)
    {
        var obj = new GameObject("Image");
        obj.layer = LayerMask.NameToLayer("UI");
        obj.transform.SetParent(parent.transform, false);

        var rect = obj.AddComponent<RectTransform>();
        var image = obj.AddComponent<Image>();
        image.sprite = sprite ?? WhiteSprite;
        image.type = Image.Type.Sliced;
        image.raycastTarget = false;

        return image;
    }

    /// <summary>
    /// 创建一个可点击的 UnityEngine.UI.Image
    /// </summary>
    public static Image CreateClickableImage(GameObject parent, Sprite? sprite = null)
    {
        var image = CreateImage(parent, sprite);
        image.raycastTarget = true;
        return image;
    }

    /// <summary>
    /// 创建一个 TextMeshProUGUI 文本组件
    /// </summary>
    public static TextMeshProUGUI CreateText(GameObject parent)
    {
        var obj = new GameObject("Text");
        obj.layer = LayerMask.NameToLayer("UI");
        obj.transform.SetParent(parent.transform, false);

        var rect = obj.AddComponent<RectTransform>();
        var tmp = obj.AddComponent<TextMeshProUGUI>();

        // 设置默认字体
        var defaultFont = TMP_Settings.defaultFontAsset;
        if (defaultFont != null)
        {
            tmp.font = defaultFont;
            tmp.fontSharedMaterial = defaultFont.material;
        }

        tmp.enableAutoSizing = false;
        tmp.enableWordWrapping = false;
        tmp.raycastTarget = false;

        return tmp;
    }

    /// <summary>
    /// 设置 RectTransform 的尺寸
    /// </summary>
    public static void SetSize(RectTransform rect, float width, float height)
    {
        rect.sizeDelta = new Vector2(width, height);
    }

    /// <summary>
    /// 设置 RectTransform 的轴心和对齐
    /// </summary>
    public static void ApplyAlignment(RectTransform rect, GUIAlignment alignment, float width, float height)
    {
        // pivot 基于对齐方式
        float pivotX = 0.5f;
        float pivotY = 0.5f;

        if (alignment.HasFlag(GUIAlignment.Left)) pivotX = 0f;
        else if (alignment.HasFlag(GUIAlignment.Right)) pivotX = 1f;

        if (alignment.HasFlag(GUIAlignment.Bottom)) pivotY = 0f;
        else if (alignment.HasFlag(GUIAlignment.Top)) pivotY = 1f;

        rect.pivot = new Vector2(pivotX, pivotY);
        rect.sizeDelta = new Vector2(width, height);
    }
}

