        tmp.text = _supplier() ?? "";
        tmp.fontSize = _style.FontSize;
        tmp.fontSizeMax = _style.FontSize;
        tmp.fontSizeMin = _style.FontSize;
        tmp.alignment = _style.Alignment;
        tmp.fontStyle = _style.Style;
        tmp.color = _style.TextColor?.ToUnityColor() ?? UColor.white;
        tmp.enableWordWrapping = true;
        tmp.ForceMeshUpdate();

        var rect = tmp.rectTransform;
        rect.sizeDelta = new Vector2(_width, tmp.preferredHeight + 0.1f);
        VanillaAsset.ApplyAlignment(rect, Alignment, rect.sizeDelta.x, rect.sizeDelta.y);

        // 持续更新需要 MonoBehaviour，这里使用简单轮询组件
        var updater = obj.AddComponent<RealtimeTextUpdater>();
        updater.TMP = tmp;
        updater.Supplier = _supplier;

        actualSize = new GUISize(rect.sizeDelta.x, rect.sizeDelta.y);
        return obj;
    }
