/// <summary>
/// 用于实时文本更新的 MonoBehaviour
/// </summary>
public class RealtimeTextUpdater : MonoBehaviour
{
    public TextMeshProUGUI? TMP;
    public System.Func<string>? Supplier;
    private string? _lastText;

    public void Update()
    {
        if (TMP == null || Supplier == null) return;
        var current = Supplier();
        if (current != _lastText)
        {
            _lastText = current;
            TMP.text = current;
            TMP.ForceMeshUpdate();
        }
    }
}

/// <summary>
/// 按钮 Widget（基于 Image + TextMeshProUGUI + PassiveButton）
/// </summary>
public class ButtonWidget : GUIWidget
{
    private readonly string _text;
    private readonly GUIClickAction _onClick;
    private readonly TextStyle _style;
    private readonly UColor _color;
    private readonly UColor _selectedColor;
    private readonly float _margin;
    private readonly GUIClickAction? _onMouseOver;
    private readonly GUIClickAction? _onMouseOut;

    public ButtonWidget(
        GUIAlignment alignment,
        TextStyle attribute,
        string text,
        GUIClickAction onClick,
        GUIClickAction? onMouseOver = null,
        GUIClickAction? onMouseOut = null,
        Color? color = null,
        Color? selectedColor = null,
        float? margin = null)
    {
        Alignment = alignment;
        _text = text;
        _onClick = onClick;
        _style = attribute;
        _onMouseOver = onMouseOver;
        _onMouseOut = onMouseOut;
        _color = color?.ToUnityColor() ?? new UColor(0.5f, 0.5f, 0.5f, 1f);
        _selectedColor = selectedColor?.ToUnityColor() ?? new UColor(0.7f, 0.7f, 0.7f, 1f);
        _margin = margin ?? 0.26f;
    }

    public override GameObject? Instantiate(GUISize available, out GUISize actualSize)
    {
        var obj = new GameObject("Button");
        obj.layer = LayerMask.NameToLayer("UI");

        // 先创建文本测量尺寸
        var tmp = VanillaAsset.CreateText(obj);
        tmp.text = _text;
        tmp.fontSize = _style.FontSize;
        tmp.fontSizeMax = _style.FontSize;
        tmp.fontSizeMin = _style.FontSize;
        tmp.alignment = TextAlignmentOptions.Center;
        tmp.fontStyle = _style.Style;
        tmp.color = _style.TextColor?.ToUnityColor() ?? UColor.white;
        tmp.ForceMeshUpdate();

        float textW = tmp.preferredWidth;
        float textH = tmp.preferredHeight;
        float btnW = textW + _margin * 2f;
        float btnH = textH + _margin * 2f;

        // 背景 Image
        var bgImage = VanillaAsset.CreateClickableImage(obj, VanillaAsset.GetButtonSprite());
        bgImage.color = _color;
        bgImage.type = Image.Type.Sliced;
        var bgRect = bgImage.rectTransform;
        bgRect.anchorMin = new Vector2(0.5f, 0.5f);
        bgRect.anchorMax = new Vector2(0.5f, 0.5f);
        bgRect.pivot = new Vector2(0.5f, 0.5f);
        bgRect.sizeDelta = new Vector2(btnW, btnH);
        bgRect.anchoredPosition = Vector2.zero;

        // 文本居中（放在背景之上）
        var textRect = tmp.rectTransform;
        textRect.anchorMin = new Vector2(0.5f, 0.5f);
        textRect.anchorMax = new Vector2(0.5f, 0.5f);
        textRect.pivot = new Vector2(0.5f, 0.5f);
        textRect.sizeDelta = new Vector2(textW, textH);
        textRect.anchoredPosition = Vector2.zero;

        // PassiveButton 交互
        var button = obj.AddComponent<PassiveButton>();
        button.OnMouseOver = new UnityEvent();
        button.OnMouseOut = new UnityEvent();
        button.OnClick = new Button.ButtonClickedEvent();

        var clickable = new GUIClickable(button);
        button.OnClick.AddListener((UnityAction)(() => _onClick?.Invoke(clickable)));
        button.OnMouseOver.AddListener((UnityAction)(() =>
        {
            bgImage.color = _selectedColor;
            _onMouseOver?.Invoke(clickable);
        }));
        button.OnMouseOut.AddListener((UnityAction)(() =>
        {
            bgImage.color = _color;
            _onMouseOut?.Invoke(clickable);
        }));

        // 设置根 RectTransform
        var rootRect = obj.GetComponent<RectTransform>();
        if (rootRect == null)
            rootRect = obj.AddComponent<RectTransform>();
        VanillaAsset.ApplyAlignment(rootRect, Alignment, btnW, btnH);

        actualSize = new GUISize(btnW, btnH);
        return obj;
    }
}

