/// <summary>
/// 纵向排列容器（手动 RectTransform 布局）
/// </summary>
public class VerticalHolderWidget : GUIWidget
{
    private readonly IEnumerable<GUIWidget?> _widgets;
    private readonly float? _fixedWidth;

    public VerticalHolderWidget(GUIAlignment alignment, IEnumerable<GUIWidget?> widgets, float? fixedWidth = null)
    {
        Alignment = alignment;
        _widgets = widgets;
        _fixedWidth = fixedWidth;
    }

    public override GameObject? Instantiate(GUISize available, out GUISize actualSize)
    {
        var obj = new GameObject("VerticalHolder");
        obj.layer = LayerMask.NameToLayer("UI");

        var results = new List<(GameObject? go, GUISize size)>();
        float totalHeight = 0f;
        float maxWidth = 0f;

        foreach (var widget in _widgets)
        {
            if (widget == null) continue;
            var childObj = widget.Instantiate(available, out var childSize);
            results.Add((childObj, childSize));
            totalHeight += childSize.Height;
            if (childSize.Width > maxWidth) maxWidth = childSize.Width;
        }

        if (_fixedWidth.HasValue)
            maxWidth = _fixedWidth.Value;

        // 从上到下排列
        float y = totalHeight * 0.5f;
        foreach (var (childObj, childSize) in results)
        {
            y -= childSize.Height * 0.5f;

            if (childObj != null)
            {
                childObj.transform.SetParent(obj.transform, false);

                float x = 0f;
                if (Alignment.HasFlag(GUIAlignment.Left))
                    x = -maxWidth * 0.5f + childSize.Width * 0.5f;
                else if (Alignment.HasFlag(GUIAlignment.Right))
                    x = maxWidth * 0.5f - childSize.Width * 0.5f;

                childObj.transform.localPosition = new Vector3(x, y, 0f);
            }

            y -= childSize.Height * 0.5f;
        }

        var rect = obj.GetComponent<RectTransform>();
        if (rect == null)
            rect = obj.AddComponent<RectTransform>();
        rect.sizeDelta = new Vector2(maxWidth, totalHeight);

        actualSize = new GUISize(maxWidth, totalHeight);
        return obj;
    }
}

/// <summary>
/// 横向排列容器（手动 RectTransform 布局）
/// </summary>
public class HorizontalHolderWidget : GUIWidget
{
    private readonly IEnumerable<GUIWidget?> _widgets;
    private readonly float? _fixedHeight;

    public HorizontalHolderWidget(GUIAlignment alignment, IEnumerable<GUIWidget?> widgets, float? fixedHeight = null)
    {
        Alignment = alignment;
        _widgets = widgets;
        _fixedHeight = fixedHeight;
    }

    public override GameObject? Instantiate(GUISize available, out GUISize actualSize)
    {
        var obj = new GameObject("HorizontalHolder");
        obj.layer = LayerMask.NameToLayer("UI");

        var results = new List<(GameObject? go, GUISize size)>();
        float totalWidth = 0f;
        float maxHeight = 0f;

        foreach (var widget in _widgets)
        {
            if (widget == null) continue;
            var childObj = widget.Instantiate(available, out var childSize);
            results.Add((childObj, childSize));
            totalWidth += childSize.Width;
            if (childSize.Height > maxHeight) maxHeight = childSize.Height;
        }

        if (_fixedHeight.HasValue)
            maxHeight = _fixedHeight.Value;

        // 从左到右排列
        float x = -totalWidth * 0.5f;
        foreach (var (childObj, childSize) in results)
        {
            x += childSize.Width * 0.5f;

            if (childObj != null)
            {
                childObj.transform.SetParent(obj.transform, false);

                float y = 0f;
                if (Alignment.HasFlag(GUIAlignment.Bottom))
                    y = -maxHeight * 0.5f + childSize.Height * 0.5f;
                else if (Alignment.HasFlag(GUIAlignment.Top))
                    y = maxHeight * 0.5f - childSize.Height * 0.5f;

                childObj.transform.localPosition = new Vector3(x, y, 0f);
            }

            x += childSize.Width * 0.5f;
        }

        var rect = obj.GetComponent<RectTransform>();
        if (rect == null)
            rect = obj.AddComponent<RectTransform>();
        rect.sizeDelta = new Vector2(totalWidth, maxHeight);

        actualSize = new GUISize(totalWidth, maxHeight);
        return obj;
    }
}

/// <summary>
/// 按每行 perLine 个排列的容器
/// </summary>
public class ArrangeWidget : GUIWidget
{
    private readonly IEnumerable<GUIWidget?> _widgets;
    private readonly int _perLine;

    public ArrangeWidget(GUIAlignment alignment, IEnumerable<GUIWidget?> widgets, int perLine)
    {
        Alignment = alignment;
        _widgets = widgets;
        _perLine = perLine;
    }

    public override GameObject? Instantiate(GUISize available, out GUISize actualSize)
    {
        var obj = new GameObject("Arrange");
        obj.layer = LayerMask.NameToLayer("UI");

        var results = new List<(GameObject? go, GUISize size)>();
        foreach (var widget in _widgets)
        {
            if (widget == null) continue;
            var childObj = widget.Instantiate(available, out var childSize);
            results.Add((childObj, childSize));
        }

        // 计算每行最大宽度和行高
        float lineWidth = 0f;
        float totalHeight = 0f;
        float currentLineMaxHeight = 0f;

        for (int i = 0; i < results.Count; i++)
        {
            lineWidth += results[i].size.Width;
            if (results[i].size.Height > currentLineMaxHeight)
                currentLineMaxHeight = results[i].size.Height;

            if ((i + 1) % _perLine == 0 || i == results.Count - 1)
            {
                totalHeight += currentLineMaxHeight;
                currentLineMaxHeight = 0f;
            }
        }

        // 布局
        float yPos = totalHeight * 0.5f;
        float xPos = 0f;
        float lineMaxHeight = 0f;
        float lineStartIdx = 0;

        for (int i = 0; i < results.Count; i++)
        {
            if (i % _perLine == 0)
            {
                // 新的一行
                if (i > 0)
                {
                    yPos -= lineMaxHeight;
                    yPos -= lineMaxHeight * 0.5f; // 补偿
                }
                xPos = -lineWidth * 0.5f; // 简化：使用最后一个 lineWidth
                lineMaxHeight = 0f;
            }

            var (childObj, childSize) = results[i];
            xPos += childSize.Width * 0.5f;

            if (childObj != null)
            {
                childObj.transform.SetParent(obj.transform, false);
                childObj.transform.localPosition = new Vector3(xPos, yPos - childSize.Height * 0.5f, 0f);
            }

            xPos += childSize.Width * 0.5f;
            if (childSize.Height > lineMaxHeight)
                lineMaxHeight = childSize.Height;
        }

        var rect = obj.GetComponent<RectTransform>();
        if (rect == null)
            rect = obj.AddComponent<RectTransform>();

        actualSize = new GUISize(lineWidth, totalHeight);
        return obj;
    }
}

