/// <summary>
/// GUI 屏幕，基于 Canvas 承载 Widget 的显示。
/// 已通过 ClassInjector 注册为 Il2Cpp 类型。
/// 使用 Unity UI 系统（Canvas / RectTransform / Image / TextMeshProUGUI）。
/// </summary>
public class MetaScreen : MonoBehaviour, IGUIScreen
{
    private GameObject? _root;
    private RectTransform? _contentRect;
    private Image? _backgroundImage;
    private GameObject? _closeButton;

    /// <summary>窗口内边距</summary>
    private const float WindowPadding = 0.3f;

    RectTransform IGUIScreen.Transform => _contentRect ?? transform as RectTransform;

    /// <summary>
    /// 生成一个完整的窗口
    /// </summary>
    /// <param name="size">窗口内容区域大小</param>
    /// <param name="parent">父级 Transform</param>
    /// <param name="localPosition">窗口位置</param>
    /// <param name="withCloseButton">是否显示关闭按钮</param>
    /// <param name="withBlackScreen">是否显示半透明黑色遮罩</param>
    public static MetaScreen GenerateWindow(
        Vector2 size,
        Transform parent,
        Vector3 localPosition,
        bool withCloseButton = true,
        bool withBlackScreen = true)
    {
        // 根节点
        var root = new GameObject("MetaWindow");
        root.layer = LayerMask.NameToLayer("UI");
        root.transform.SetParent(parent, false);
        root.transform.localPosition = localPosition;

        var rootRect = root.AddComponent<RectTransform>();
        rootRect.anchorMin = new Vector2(0.5f, 0.5f);
        rootRect.anchorMax = new Vector2(0.5f, 0.5f);
        rootRect.pivot = new Vector2(0.5f, 0.5f);
        rootRect.sizeDelta = size + new Vector2(WindowPadding * 2f, WindowPadding * 2f);

        // 黑色遮罩
        if (withBlackScreen)
        {
            var blackObj = new GameObject("BlackScreen");
            blackObj.layer = LayerMask.NameToLayer("UI");
            blackObj.transform.SetParent(root.transform, false);
            var blackRect = blackObj.AddComponent<RectTransform>();
            blackRect.anchorMin = Vector2.zero;
            blackRect.anchorMax = Vector2.one;
            blackRect.sizeDelta = new Vector2(30f, 30f);
            blackRect.anchoredPosition = Vector2.zero;
            var blackImage = blackObj.AddComponent<Image>();
            blackImage.sprite = VanillaAsset.GetFullScreenSprite();
            blackImage.type = Image.Type.Sliced;
            blackImage.color = new UColor(0f, 0f, 0f, 0.5f);
            blackImage.raycastTarget = true;
        }

        // 窗口背景
        var bgObj = new GameObject("WindowBackground");
        bgObj.layer = LayerMask.NameToLayer("UI");
        bgObj.transform.SetParent(root.transform, false);
        var bgRect = bgObj.AddComponent<RectTransform>();
        bgRect.anchorMin = new Vector2(0.5f, 0.5f);
        bgRect.anchorMax = new Vector2(0.5f, 0.5f);
        bgRect.pivot = new Vector2(0.5f, 0.5f);
        bgRect.sizeDelta = rootRect.sizeDelta;
        bgRect.anchoredPosition = Vector2.zero;
        var bgImage = bgObj.AddComponent<Image>();
        bgImage.sprite = VanillaAsset.GetWindowSprite();
        bgImage.type = Image.Type.Sliced;
        bgImage.color = UColor.white;
        bgImage.raycastTarget = true;

        // 内容屏幕
        var screenObj = new GameObject("Screen");
        screenObj.layer = LayerMask.NameToLayer("UI");
        screenObj.transform.SetParent(bgObj.transform, false);
        var screenRect = screenObj.AddComponent<RectTransform>();
        screenRect.anchorMin = new Vector2(0.5f, 0.5f);
        screenRect.anchorMax = new Vector2(0.5f, 0.5f);
        screenRect.pivot = new Vector2(0.5f, 0.5f);
        screenRect.sizeDelta = size;
        screenRect.anchoredPosition = Vector2.zero;

        var screen = screenObj.AddComponent<MetaScreen>();
        screen._root = root;
        screen._contentRect = screenRect;
        screen._backgroundImage = bgImage;

        // 关闭按钮
        if (withCloseButton)
        {
            var totalW = rootRect.sizeDelta.x;
            var totalH = rootRect.sizeDelta.y;
            screen._closeButton = CreateCloseButton(root.transform, new Vector2(totalW * 0.5f - 0.2f, totalH * 0.5f - 0.2f), screen);
        }

        return screen;
    }

    /// <summary>
    /// 生成一个透明窗口（无背景，无遮罩）
    /// </summary>
    public static MetaScreen GenerateBlankWindow(Vector2 size, Transform parent, Vector3 localPosition)
    {
        var root = new GameObject("MetaWindow");
        root.layer = LayerMask.NameToLayer("UI");
        root.transform.SetParent(parent, false);
        root.transform.localPosition = localPosition;

        var rootRect = root.AddComponent<RectTransform>();
        rootRect.anchorMin = new Vector2(0.5f, 0.5f);
        rootRect.anchorMax = new Vector2(0.5f, 0.5f);
        rootRect.pivot = new Vector2(0.5f, 0.5f);
        rootRect.sizeDelta = size;

        var screenObj = new GameObject("Screen");
        screenObj.layer = LayerMask.NameToLayer("UI");
        screenObj.transform.SetParent(root.transform, false);
        var screenRect = screenObj.AddComponent<RectTransform>();
        screenRect.anchorMin = new Vector2(0.5f, 0.5f);
        screenRect.anchorMax = new Vector2(0.5f, 0.5f);
        screenRect.pivot = new Vector2(0.5f, 0.5f);
        screenRect.sizeDelta = size;
        screenRect.anchoredPosition = Vector2.zero;

        var screen = screenObj.AddComponent<MetaScreen>();
        screen._root = root;
        screen._contentRect = screenRect;

        return screen;
    }

    /// <summary>
    /// 设置屏幕上显示的 Widget
    /// </summary>
    public void SetWidget(GUIWidget? widget, out GUISize actualSize)
    {
        // 清除已有内容
        for (int i = _contentRect.childCount - 1; i >= 0; i--)
        {
            Destroy(_contentRect.GetChild(i).gameObject);
        }

        if (widget == null)
        {
            actualSize = GUISize.Zero;
            return;
        }

        var obj = widget.Instantiate(new GUISize(100f, 100f), out actualSize);
        if (obj != null)
        {
            obj.transform.SetParent(_contentRect, false);
            obj.transform.localPosition = Vector3.zero;
        }
    }

    /// <summary>
    /// 关闭并销毁窗口
    /// </summary>
    public void Close()
    {
        if (_root != null)
        {
            Destroy(_root);
            _root = null;
        }
    }

    void OnDestroy()
    {
        if (_root != null)
        {
            Destroy(_root);
            _root = null;
        }
    }

    /// <summary>
    /// 创建关闭按钮（Unity UI 版本）
    /// </summary>
    private static GameObject CreateCloseButton(Transform parent, Vector2 anchoredPos, MetaScreen screen)
    {
        var obj = new GameObject("CloseButton");
        obj.layer = LayerMask.NameToLayer("UI");
        obj.transform.SetParent(parent, false);

        var rect = obj.AddComponent<RectTransform>();
        rect.anchorMin = new Vector2(0.5f, 0.5f);
        rect.anchorMax = new Vector2(0.5f, 0.5f);
        rect.pivot = new Vector2(0.5f, 0.5f);
        rect.anchoredPosition = anchoredPos;

        var btnSize = 0.4f;
        rect.sizeDelta = new Vector2(btnSize, btnSize);

        var image = obj.AddComponent<Image>();
        image.sprite = VanillaAsset.GetButtonSprite();
        image.type = Image.Type.Sliced;
        image.color = new UColor(0.8f, 0.2f, 0.2f, 1f);
        image.raycastTarget = true;

        // "X" 文本
        var textObj = new GameObject("Text");
        textObj.layer = LayerMask.NameToLayer("UI");
        textObj.transform.SetParent(obj.transform, false);
        var tmp = VanillaAsset.CreateText(textObj);
        tmp.text = "X";
        tmp.fontSize = 2f;
        tmp.fontSizeMax = 2f;
        tmp.fontSizeMin = 2f;
        tmp.alignment = TextAlignmentOptions.Center;
        tmp.color = UColor.white;
        tmp.ForceMeshUpdate();

        var textRect = tmp.rectTransform;
        textRect.anchorMin = new Vector2(0.5f, 0.5f);
        textRect.anchorMax = new Vector2(0.5f, 0.5f);
        textRect.pivot = new Vector2(0.5f, 0.5f);
        textRect.sizeDelta = new Vector2(btnSize, btnSize);
        textRect.anchoredPosition = Vector2.zero;

        var button = obj.AddComponent<PassiveButton>();
        button.OnMouseOver = new UnityEvent();
        button.OnMouseOut = new UnityEvent();
        button.OnClick = new Button.ButtonClickedEvent();
        button.OnClick.AddListener((UnityAction)(() => screen.Close()));
        button.OnMouseOver.AddListener((UnityAction)(() => { image.color = new UColor(1f, 0.4f, 0.4f, 1f); }));
        button.OnMouseOut.AddListener((UnityAction)(() => { image.color = new UColor(0.8f, 0.2f, 0.2f, 1f); }));

        return obj;
    }

