namespace LightInDark.UI.Window;

/// <summary>
/// 高级 UI 辅助类，提供常用窗口的快捷创建方法。
/// 对应 Nebula 的 MetaUI / MetaDialog 系统。
/// </summary>
public static class MetaUI
{
    /// <summary>
    /// 按钮窗口选项
    /// </summary>
    public readonly struct ButtonOption
    {
        public readonly string Label;
        public readonly Action OnClick;
        public readonly Color? Color;

        public ButtonOption(string label, Action onClick, Color? color = null)
        {
            Label = label;
            OnClick = onClick;
            Color = color;
        }
    }

    /// <summary>
    /// 打开一个按钮选择窗口
    /// </summary>
    /// <param name="title">窗口标题</param>
    /// <param name="options">按钮选项</param>
    public static MetaScreen OpenButtonWindow(string title, params ButtonOption[] options)
    {
        var gui = LIDGUI.Instance;
        var widgets = new List<GUIWidget?>();

        // 标题
        widgets.Add(gui.Text(GUIAlignment.Center, TextStyle.Title, title));
        widgets.Add(gui.VerticalMargin(0.3f));

        // 按钮列表
        foreach (var opt in options)
        {
            var localOpt = opt;
            widgets.Add(gui.RawButton(
                GUIAlignment.Center,
                TextStyle.Default,
                localOpt.Label,
                clickable => { localOpt.OnClick?.Invoke(); },
                color: localOpt.Color
            ));
            widgets.Add(gui.VerticalMargin(0.1f));
        }

        // 关闭按钮
        widgets.Add(gui.VerticalMargin(0.2f));
        widgets.Add(gui.RawButton(
            GUIAlignment.Center,
            TextStyle.Small,
            "关闭",
            clickable => { },
            color: Color.Gray
        ));

        var content = gui.VerticalHolder(GUIAlignment.Center, widgets.ToArray());

        var screen = MetaScreen.GenerateWindow(
            new Vector2(4.5f, 3f),
            GetParent(),
            Vector3.zero,
            withCloseButton: true,
            withBlackScreen: true
        );

        screen.SetWidget(content, out _);
        return screen;
    }

    /// <summary>
    /// 打开一个确认对话框（是/否）
    /// </summary>
    /// <param name="message">提示消息</param>
    /// <param name="onConfirm">点击"是"后的回调</param>
    /// <param name="onCancel">点击"否"后的回调（可为 null）</param>
    public static MetaScreen OpenConfirmDialog(string message, Action onConfirm, Action? onCancel = null)
    {
        var gui = LIDGUI.Instance;
        var localOnCancel = onCancel;

        var content = gui.VerticalHolder(
            GUIAlignment.Center,
            gui.Text(GUIAlignment.Center, TextStyle.Default, message),
            gui.VerticalMargin(0.3f),
            gui.HorizontalHolder(
                GUIAlignment.Center,
                gui.RawButton(
                    GUIAlignment.Center,
                    TextStyle.Default,
                    "是",
                    clickable => { onConfirm?.Invoke(); },
                    color: Color.Green
                ),
                gui.HorizontalMargin(0.3f),
                gui.RawButton(
                    GUIAlignment.Center,
                    TextStyle.Default,
                    "否",
                    clickable => { localOnCancel?.Invoke(); },
                    color: Color.Red
                )
            )
        );

        var screen = MetaScreen.GenerateWindow(
            new Vector2(3.9f, 1.5f),
            GetParent(),
            Vector3.zero,
            withCloseButton: false,
            withBlackScreen: true
        );

        screen.SetWidget(content, out _);
        return screen;
    }

    /// <summary>
    /// 打开一个消息对话框（仅含"确定"按钮）
    /// </summary>
    /// <param name="message">消息内容</param>
    /// <param name="onClose">关闭时的回调（可为 null）</param>
    public static MetaScreen OpenMessageDialog(string message, Action? onClose = null)
    {
        var gui = LIDGUI.Instance;
        var localOnClose = onClose;

        var content = gui.VerticalHolder(
            GUIAlignment.Center,
            gui.Text(GUIAlignment.Center, TextStyle.Default, message),
            gui.VerticalMargin(0.3f),
            gui.RawButton(
                GUIAlignment.Center,
                TextStyle.Default,
                "确定",
                clickable => { localOnClose?.Invoke(); }
            )
        );

        var screen = MetaScreen.GenerateWindow(
            new Vector2(3.5f, 1.5f),
            GetParent(),
            Vector3.zero,
            withCloseButton: false,
            withBlackScreen: true
        );

        screen.SetWidget(content, out _);
        return screen;
    }

    /// <summary>
    /// 打开一个文本展示窗口（带标题）
    /// </summary>
    /// <param name="title">标题</param>
    /// <param name="text">内容</param>
    public static MetaScreen OpenTextWindow(string title, string text)
    {
        var gui = LIDGUI.Instance;

        var content = gui.VerticalHolder(
            GUIAlignment.Center,
            gui.Text(GUIAlignment.Center, TextStyle.Title, title),
            gui.VerticalMargin(0.2f),
            gui.Text(GUIAlignment.Left, TextStyle.Default, text)
        );

        var screen = MetaScreen.GenerateWindow(
            new Vector2(5f, 3f),
            GetParent(),
            Vector3.zero,
            withCloseButton: true,
            withBlackScreen: true
        );

        screen.SetWidget(content, out _);
        return screen;
    }

    /// <summary>
    /// 打开一个自定义内容窗口（带标题）
    /// </summary>
    /// <param name="title">标题</param>
    /// <param name="contentWidget">自定义 Widget 内容</param>
    /// <param name="windowSize">窗口大小</param>
    public static MetaScreen OpenCustomWindow(string title, GUIWidget contentWidget, Vector2? windowSize = null)
    {
        var gui = LIDGUI.Instance;

        var content = gui.VerticalHolder(
            GUIAlignment.Center,
            gui.Text(GUIAlignment.Center, TextStyle.Title, title),
            gui.VerticalMargin(0.2f),
            contentWidget
        );

        var screen = MetaScreen.GenerateWindow(
            windowSize ?? new Vector2(5f, 3f),
            GetParent(),
            Vector3.zero,
            withCloseButton: true,
            withBlackScreen: true
        );

        screen.SetWidget(content, out _);
        return screen;
    }

    private static Transform GetParent()
    {
        if (HudManager.Instance != null)
            return HudManager.Instance.transform;

        // 降级：创建临时父级
        var go = new GameObject("MetaUI_TempParent");
        UnityEngine.Object.DontDestroyOnLoad(go);
        return go.transform;
    }
}

using UnityEngine;

namespace LightInDark.UI.Window;

/// <summary>
/// Widget 扩展方法，对应 Nebula 的 GUIWidgetHelpers。
/// 提供链式调用的布局修饰。
/// </summary>
public static class GUIWidgetHelpers
{
    /// <summary>添加四周留白</summary>
    public static GUIWidget WithRoom(this GUIWidget inner, Vector2 margin)
    {
        var gui = LIDGUI.Instance;

        if (margin.x > 0f)
        {
            var xMargin = gui.HorizontalMargin(margin.x * 0.5f);
            inner = gui.HorizontalHolder(inner.Alignment, xMargin, inner, xMargin);
        }
        if (margin.y > 0f)
        {
            var yMargin = gui.VerticalMargin(margin.y * 0.5f);
            inner = gui.VerticalHolder(inner.Alignment, yMargin, inner, yMargin);
        }
        return inner;
    }

    /// <summary>偏移 Widget 位置</summary>
    public static GUIWidget Move(this GUIWidget inner, Vector2 diff)
    {
        var gui = LIDGUI.Instance;

        if (diff.x > 0f)
            inner = gui.HorizontalHolder(inner.Alignment, gui.HorizontalMargin(diff.x), inner);
        if (diff.x < 0f)
            inner = gui.HorizontalHolder(inner.Alignment, inner, gui.HorizontalMargin(-diff.x));

        if (diff.y > 0f)
            inner = gui.VerticalHolder(inner.Alignment, gui.VerticalMargin(diff.y), inner);
        if (diff.y < 0f)
            inner = gui.VerticalHolder(inner.Alignment, inner, gui.VerticalMargin(-diff.y));

        return inner;
    }
}

