        GameObject holder = UnityHelper.CreateObject("DualButton", null, UnityEngine.Vector3.zero, LayerExpansion.GetUILayer());

        GenerateButton(holder.transform, true);
        GenerateButton(holder.transform, false);

        return holder;
    }
}

