/// <summary>
/// 実際にボタンをとりまとめるグループ
/// </summary>
file class GUIButtonGroupInstance
{
    internal class GUIButtonInstance(Action unselect, Action select) : IGUISelectable
    {
        public void Unselect()
        {
            IsSelected = false;
            unselect.Invoke();
        }
        public void Select()
        {
            IsSelected = true;
            select.Invoke();
        }
        public bool IsSelected { get; set; } = false;
    }
    static public GUIButtonGroupInstance? CurrentInstance { get; private set; }

    private List<GUIButtonInstance> buttons = [];

    public GUIButtonGroupInstance(GUIButtonGroupProperty groupProp)
    {
        GroupProp = groupProp;
    }

    public IReadOnlyList<GUIButtonInstance> Buttons => buttons;

    public GUIButtonGroupProperty GroupProp { get; private init; }

    public void AddButton(GUIButtonInstance button) => buttons.Add(button);
    public void UnselectAll() => buttons.Do(b => b.Unselect());
    public void Select(GUIButtonInstance button)
    {
        UnselectAll();
        button.Select();
    }

    static public void Refresh()
    {
        CurrentInstance = null;
    }

    static public void Call(GUIButtonGroupProperty groupProp)
    {
        CurrentInstance = new(groupProp);
    }
}

internal record GUIButtonGroupProperty(bool AllowMultipleChoice)
{
    static public GUIButtonGroupProperty Default = new(false);
}


/// <summary>
/// ボタンをグループ化するウィジェットです。
/// </summary>
internal class GUIButtonGroup : Virial.Media.GUIWidget
{
    private Virial.Media.GUIWidget innerWidget;
    internal GUIButtonGroup(Virial.Media.GUIWidget inner)
    {
        innerWidget = inner;
    }
    public GUIButtonGroupProperty GroupProperty { get; private set; } = GUIButtonGroupProperty.Default;
    internal override GUIAlignment Alignment => innerWidget.Alignment;
    internal override GameObject? Instantiate(Size size, out Size actualSize)
    {
        try
        {
            GUIButtonGroupInstance.Call(GroupProperty);
            return innerWidget.Instantiate(size, out actualSize);
        }
        finally
        {
            GUIButtonGroupInstance.Refresh();
        }
    }
    internal override GameObject? Instantiate(Anchor anchor, Size size, out Size actualSize)
    {
        try
        {
            GUIButtonGroupInstance.Call(GroupProperty);
            return innerWidget.Instantiate(anchor, size, out actualSize);
        }
        finally
        {
            GUIButtonGroupInstance.Refresh();
        }
    }
}

/// <summary>
/// モダンデザインのボタンです。グループ化できます。
/// </summary>
internal class GUIModernButton : NoSGUIText
{
    static private MultiImage modernButtonSprite = DividedExpandableSpriteLoader.FromResource("Nebula.Resources.GUI.Button.png", 150f, 12, 12, 3, 2);
    static private MultiImage modernCheckSprite = DividedSpriteLoader.FromResource("Nebula.Resources.GUI.Checkmark.png", 150f, 2, 1);
    static internal Sprite ModernCheckBackSprite => modernCheckSprite.GetSprite(0);
    static internal Sprite ModernCheckSprite => modernCheckSprite.GetSprite(1);
    public GUIClickableAction? OnClick { get; init; }
    public GUIClickableAction? OnRightClick { get; init; }
    public GUIClickableAction? OnMouseOver { get; init; }
    public GUIClickableAction? OnMouseOut { get; init; }

    public string RawText { init { Text = new RawTextComponent(value); } }
    public string TranslationKey { init { Text = new TranslateTextComponent(value); } }
    public bool AsMaskedButton { get; init; }
    public float TextMargin { get; init; } = 0.05f;

    public bool SelectedDefault { get; init; } = false; //デフォルトで選択状態の場合はtrue
    public bool WithCheckMark { get; init; } = false;
    public bool EmphasizeOnSelected { get; init; } = true;
    public bool BlockSelectingOnClicked { get; init; } = false;

    override protected bool AllowGenerateCollider => false;

    public GUIModernButton(GUIAlignment alignment, Virial.Text.TextAttribute attribute, TextComponent text) : base(alignment, attribute, text)
    {
        AsMaskedButton = attribute.Font.FontMaterial != null;
    }

    static private Virial.Color piledModernColor = new(41 * 0.5f / 255f, 235 * 0.5f / 255f, 198 * 0.5f / 255f);
    static private Virial.Color selectedModernColor = new(16, 16, 16);

    internal override GameObject? Instantiate(Size size, out Size actualSize)
    {
        var inner = base.Instantiate(size, out actualSize)!;

        var margin = TextMargin;

        var button = UnityHelper.CreateObject<SpriteRenderer>("Button", null, UnityEngine.Vector3.zero, LayerExpansion.GetUILayer());
        button.sprite = modernButtonSprite.GetSprite((SelectedDefault && EmphasizeOnSelected) ? 3 : 0);
        button.drawMode = SpriteDrawMode.Sliced;
        button.tileMode = SpriteTileMode.Continuous;
        button.size = actualSize.ToUnityVector() + new UnityEngine.Vector2(margin * 0.84f, margin * 0.84f);
        if (AsMaskedButton) button.maskInteraction = SpriteMaskInteraction.VisibleInsideMask;

        inner.transform.SetParent(button.transform);
        inner.transform.localPosition += new UnityEngine.Vector3(0, 0, -0.05f);

        var collider = button.gameObject.AddComponent<BoxCollider2D>();
        collider.size = actualSize.ToUnityVector() + new UnityEngine.Vector2(margin * 0.6f, margin * 0.6f);
        collider.isTrigger = true;

        var passiveButton = button.gameObject.SetUpButton(true);

        var innerText = inner.GetComponent<TextMeshPro>();
        innerText.outlineColor = UnityEngine.Color.clear;

        GameObject? checkMark = null;
        if (WithCheckMark)
        {
            var checkMarkBack = UnityHelper.CreateObject<SpriteRenderer>("Checkmark", button.transform, (actualSize.ToUnityVector() * 0.5f).AsVector3(-1f) + new UnityEngine.Vector3(-0.05f, -0.05f, 0f));
            checkMark = checkMarkBack.gameObject;
            checkMarkBack.sprite = modernCheckSprite.GetSprite(0);
            checkMarkBack.maskInteraction = button.maskInteraction;

            var checkMarkFront = UnityHelper.CreateObject<SpriteRenderer>("Checkmark", checkMarkBack.transform, new(0.02f, 0.01f, -0.1f));
            checkMarkFront.sprite = modernCheckSprite.GetSprite(1);
            checkMarkFront.maskInteraction = button.maskInteraction;
            checkMarkFront.gameObject.SetActive(true);

            checkMark.SetActive(SelectedDefault);

            button.gameObject.AddComponent<SortingGroup>();
        }

        var piledText = Text?.Color(piledModernColor);
        var selectedText = Text?.Color(selectedModernColor);

        var currentInstance = GUIButtonGroupInstance.CurrentInstance;
        GUIButtonGroupInstance.GUIButtonInstance? buttonInstance = null;
        if (currentInstance != null) {
            buttonInstance = new(
                () =>
                {
                    var isPiled = passiveButton.IsPiled();
                    button.sprite = modernButtonSprite.GetSprite(isPiled ? 1 : 0);
                    if (Text != null) innerText.text = (isPiled ? piledText : Text)!.GetString();
                    if (checkMark) checkMark!.SetActive(false);
                },
                () =>
                {
                    var isPiled = passiveButton.IsPiled();
                    if (EmphasizeOnSelected) button.sprite = modernButtonSprite.GetSprite(isPiled ? 4 : 3);
                    if (Text != null) innerText.text = selectedText!.GetString();
                    if (checkMark) checkMark!.SetActive(true);
                }
                )
            { IsSelected = SelectedDefault };

            currentInstance.AddButton(buttonInstance);
            if (!BlockSelectingOnClicked) passiveButton.OnClick.AddListener(() => currentInstance.Select(buttonInstance));
        }

        GUIClickable clickable = new(passiveButton, buttonInstance != null ? new GUIHarmoniousSelectable(buttonInstance, currentInstance!) : null);

        //マウスカーソルを合わせたとき
        passiveButton.OnMouseOver.AddListener(() =>
        {
            var selected = (buttonInstance?.IsSelected ?? false) && EmphasizeOnSelected;
            button.sprite = modernButtonSprite.GetSprite(selected ? 4 : 1);
            if (Text != null) innerText.text = (selected ? selectedText : piledText)!.GetString();
        });
        passiveButton.OnMouseOut.AddListener(() =>
        {
            var selected = (buttonInstance?.IsSelected ?? false) && EmphasizeOnSelected;
            button.sprite = modernButtonSprite.GetSprite(selected ? 3 : 0);
            if (Text != null) innerText.text = (selected ? selectedText : Text)!.GetString();
        });

        //テキスト色の変更
        if (Text != null && SelectedDefault) innerText.text = selectedText!.GetString();

        if (OnClick != null) passiveButton.OnClick.AddListener(() => OnClick(clickable));
        if (OnMouseOut != null) passiveButton.OnMouseOut.AddListener(() => OnMouseOut(clickable));
        if (OnMouseOver != null) passiveButton.OnMouseOver.AddListener(() => OnMouseOver(clickable));

        if (OverlayWidget != null)
        {
#if PC
            passiveButton.OnMouseOver.AddListener(() => NebulaManager.Instance.SetHelpWidget(passiveButton, OverlayWidget()));
            passiveButton.OnMouseOut.AddListener(() => NebulaManager.Instance.HideHelpWidgetIf(passiveButton));
#elif ANDROID
            if(OnClick == null){
                passiveButton.OnClick.AddListener(() => NebulaManager.Instance.SetHelpWidget(passiveButton, OverlayWidget()));
            }
#endif
        }

        if (OnRightClick != null) passiveButton.gameObject.AddComponent<ExtraPassiveBehaviour>().OnRightClicked += () => OnRightClick(clickable);

        actualSize.Width += margin + 0.1f;
        actualSize.Height += margin + 0.1f;

        return button.gameObject;
    }
}

using Nebula.Roles;
using TMPro;
using Virial.Compat;
using Virial.Media;
using Virial.Text;

namespace Nebula.Modules.GUIWidget;


public class NoSGUIText : AbstractGUIWidget
{
    protected Virial.Text.TextAttribute Attr;
    protected TextComponent? Text;
    public GUIWidgetSupplier? OverlayWidget { get; init; } = null;
    public (Action action, bool reopenOverlay)? OnClickText { get; init; } = null;

    /// <summary>
    /// NoSGUITextにオーバーレイ表示やクリック操作を委任する場合はtrueにしてください。
    /// </summary>
    virtual protected bool AllowGenerateCollider => true;
    public Action<TextMeshPro>? PostBuilder = null;

    public NoSGUIText(GUIAlignment alignment, Virial.Text.TextAttribute attribute, TextComponent? text) : base(alignment)
    {
        Attr = attribute;
        Text = text;
    }

    protected void ReflectMyAttribute(TMPro.TextMeshPro text, float width) => ReflectAttribute(Attr, text, width);
    static public void ReflectAttribute(TextAttribute attr, TMPro.TextMeshPro text, float width)
    {
        text.color = attr.Color.ToUnityColor();
        text.alignment = (TMPro.TextAlignmentOptions)attr.Alignment;
        text.fontStyle = (TMPro.FontStyles)attr.Style;
        text.fontSize = attr.FontSize.FontSizeDefault;
        text.fontSizeMin = attr.FontSize.FontSizeMin;
        text.fontSizeMax = attr.FontSize.FontSizeMax;
        text.enableAutoSizing = attr.FontSize.AllowAutoSizing;
        text.enableWordWrapping = attr.Wrapping;
        text.rectTransform.sizeDelta = new(Mathn.Min(width, attr.Size.Width), attr.Size.Height);
        text.rectTransform.anchorMin = new UnityEngine.Vector2(0.5f, 0.5f);
        text.rectTransform.anchorMax = new UnityEngine.Vector2(0.5f, 0.5f);
        text.rectTransform.pivot = new UnityEngine.Vector2(0.5f, 0.5f);
        text.UseRoleIcon();

        if (attr.Font != null)
        {
            text.font = attr.Font.Font;
            if (attr.Font.FontMaterial != null) text.fontMaterial = attr.Font.FontMaterial;
        }
        if (attr.OutlineWidth.HasValue) text.SetOutlineThickness(attr.OutlineWidth.Value);
    }

    internal override GameObject? Instantiate(Size size, out Size actualSize)
    {
        if (Text == null)
        {
            actualSize = new(0f, 0f);
            return null;
        }

        var text = UnityEngine.Object.Instantiate(VanillaAsset.StandardTextPrefab, null);
        text.transform.localPosition = new UnityEngine.Vector3(0f, 0f, 0f);

        ReflectMyAttribute(text, size.Width);
        text.text = Text.GetString();
        text.sortingOrder = 10;


        text.ForceMeshUpdate();

        if (Attr.IsFlexible)
        {
            if (text.enableWordWrapping)
            {
                float width = Math.Min(text.rectTransform.sizeDelta.x, text.textBounds.size.x);
                float height = text.textBounds.size.y;
                text.rectTransform.sizeDelta = new(width, height);
            }
            else
            {
                float prefferedWidth = Math.Min(text.rectTransform.sizeDelta.x, text.preferredWidth);
                float prefferedHeight = Math.Min(text.rectTransform.sizeDelta.y, text.preferredHeight);
                text.rectTransform.sizeDelta = new(prefferedWidth, prefferedHeight);
            }

            text.ForceMeshUpdate();
        }


        if (AllowGenerateCollider && (OverlayWidget != null || OnClickText != null))
        {
            var button = text.gameObject.SetUpButton(false);
            var collider = text.gameObject.AddComponent<BoxCollider2D>();
            collider.isTrigger = true;
            collider.size = text.rectTransform.sizeDelta;

            if (OverlayWidget != null)
            {
#if PC
                button.OnMouseOver.AddListener(() => NebulaManager.Instance.SetHelpWidget(button, OverlayWidget()));
                button.OnMouseOut.AddListener(() => NebulaManager.Instance.HideHelpWidgetIf(button));
#elif ANDROID
                if(OnClickText == null){
                    button.OnClick.AddListener(() => NebulaManager.Instance.SetHelpWidget(button, OverlayWidget()));    
                }
#endif
            }
            if (OnClickText != null)
            {
                button.OnClick.AddListener(() =>
                {
                    OnClickText.Value.action.Invoke();
                    if (OnClickText.Value.reopenOverlay)
                    {
                        button.OnMouseOut.Invoke();
                        button.OnMouseOver.Invoke();
                    }
                });
            }
        }

        PostBuilder?.Invoke(text);

        actualSize = new Size(text.rectTransform.sizeDelta);
        return text.gameObject;
    }
}

public class NoSGUICheckbox : AbstractGUIWidget
{
    internal ListArtifact<(Func<bool> getter, Action toggle)> Artifact = new();
    private bool defaultValue;
    public Action<bool>? OnValueChanged = null;
    public NoSGUICheckbox(GUIAlignment alignment, bool defaultValue) : base(alignment)
    {
        this.defaultValue = defaultValue;
    }


    internal override GameObject? Instantiate(Size size, out Size actualSize)
    {
        bool currentValue = defaultValue;

        var backText = UnityEngine.Object.Instantiate(VanillaAsset.StandardTextPrefab, null);
        backText.transform.localPosition = new UnityEngine.Vector3(0f, 0f, 0f);

        var text = UnityEngine.Object.Instantiate(VanillaAsset.StandardTextPrefab, backText.transform);
        text.transform.localPosition = new UnityEngine.Vector3(0f, 0f, -0.1f);


        NoSGUIText.ReflectAttribute(GUI.API.GetAttribute(AttributeAsset.CenteredBold), backText, size.Width);
        NoSGUIText.ReflectAttribute(GUI.API.GetAttribute(AttributeAsset.CenteredBold), text, size.Width);
        backText.sortingOrder = 10;
        backText.color = Color.white;
        text.sortingOrder = 11;
        text.color = Color.green;

        void UpdateText() => text.text = currentValue ? "✓" : "";

        backText.text = "□";
        text.text = "✓";

        backText.ForceMeshUpdate();
        text.ForceMeshUpdate();

        backText.rectTransform.sizeDelta = new(backText.preferredWidth, backText.preferredHeight);
        text.rectTransform.sizeDelta = new(text.preferredWidth, text.preferredHeight);

        UpdateText();

        backText.ForceMeshUpdate();
        text.ForceMeshUpdate();


        var button = text.gameObject.SetUpButton(true);
        var collider = text.gameObject.AddComponent<BoxCollider2D>();
        collider.isTrigger = true;
        collider.size = text.rectTransform.sizeDelta;

        button.OnMouseOver.AddListener(() => backText.color = Color.green);
        button.OnMouseOut.AddListener(() => backText.color = Color.white);
        button.OnClick.AddListener(() => { currentValue = !currentValue; UpdateText(); OnValueChanged?.Invoke(currentValue); });

        Artifact.Values.Add((() => currentValue, button.OnClick.Invoke));

        actualSize = new Size(text.rectTransform.sizeDelta);
        return backText.gameObject;
    }
}

using Il2CppInterop.Runtime.Injection;
using Virial.Compat;
using Virial.Media;

namespace Nebula.Modules.GUIWidget;

public class NoSGUIImage : AbstractGUIWidget
{
    protected Virial.Media.Image? Image;
    protected FuzzySize Size;
    public Virial.Color? Color = null;
    public GUIClickableAction? OnClick;
    public GUIWidgetSupplier? Overlay;
    public bool IsMasked { get; init; }
    public Action<SpriteRenderer>? PostBuilder = null;

    public NoSGUIImage(GUIAlignment alignment, Virial.Media.Image? image, FuzzySize size,Virial.Color? color = null, GUIClickableAction? onClick = null, GUIWidgetSupplier? overlay = null) : base(alignment)
    {
        this.Image = image;
        this.Size = size;
        this.Color = color;
        this.OnClick = onClick;
        this.Overlay = overlay;
    }

    internal override GameObject? Instantiate(Size size, out Size actualSize)
    {
        try
        {
            if (Image?.GetSprite() == null)
            {
                actualSize = new(0f, 0f);
                return null;
            }

            var renderer = UnityHelper.CreateObject<SpriteRenderer>("Image", null, UnityEngine.Vector3.zero, LayerExpansion.GetUILayer());
            renderer.sprite = Image.GetSprite();
            renderer.sortingOrder = 10;
            if (IsMasked) renderer.maskInteraction = SpriteMaskInteraction.VisibleInsideMask;

            var spriteSize = renderer.sprite.bounds.size;
            float scale = Math.Min(
                Size.Width.HasValue ? (Size.Width.Value / spriteSize.x) : float.MaxValue,
                Size.Height.HasValue ? (Size.Height.Value / spriteSize.y) : float.MaxValue
                );
            renderer.transform.localScale = UnityEngine.Vector3.one * scale;

            if (Color != null) renderer.color = Color.Value.ToUnityColor();

            actualSize = new(spriteSize.x * scale, spriteSize.y * scale);

            if (OnClick != null || Overlay != null)
            {
                VColor rendererColor = new(renderer.color);
                var button = renderer.gameObject.SetUpButton(false, renderer, rendererColor, rendererColor * new VColor(0.7f, 1f, 0.7f));
                var collider = renderer.gameObject.AddComponent<BoxCollider2D>();
                collider.size = renderer.sprite.bounds.size;
                collider.isTrigger = true;

                GUIClickable clickable = new(button);
                if (OnClick != null) button.OnClick.AddListener(() => { VanillaAsset.PlaySelectSE(); OnClick.Invoke(clickable); });
                if (Overlay != null)
                {
                    button.OnMouseOver.AddListener(() => { VanillaAsset.PlayHoverSE(); NebulaManager.Instance.SetHelpWidget(button, Overlay()); });
                    button.OnMouseOut.AddListener(() => { NebulaManager.Instance.HideHelpWidgetIf(button); });
                }
            }

            PostBuilder?.Invoke(renderer);

            return renderer.gameObject;
        }
        catch
        {
            actualSize = new(0f, 0f);
            return null;
        }
    }
}

