        Style = other.Style;
        FontSize = other.FontSize;
        Size = other.Size;
        Color = other.Color;
        IsFlexible = other.IsFlexible;
        Wrapping = other.Wrapping;
        OutlineWidth = other.OutlineWidth;
    }
}

/// <summary>
