// =====================================================================
// NoSGUIText — 文本 Widget（基于 TextMeshPro，克隆 StandardTextPrefab）
// =====================================================================

public class NoSGUIText : AbstractGUIWidget
{
    protected TextAttribute Attr;
    protected TextComponent? Text;
    public Action<TextMeshPro>? PostBuilder;

    public NoSGUIText(GUIAlignment alignment, TextAttribute attribute, TextComponent? text) : base(alignment)
    {
        Attr = attribute;
        Text = text;
    }

    protected static void ReflectAttribute(TextAttribute attr, TextMeshPro text, float width)
    {
        text.color = attr.Color.ToUnityColor();
        text.alignment = (TextAlignmentOptions)attr.Alignment;
        text.fontStyle = (FontStyles)attr.Style;
        text.fontSize = attr.FontSize.FontSizeDefault;
        text.fontSizeMin = attr.FontSize.FontSizeMin;
        text.fontSizeMax = attr.FontSize.FontSizeMax;
        text.enableAutoSizing = attr.FontSize.AllowAutoSizing;
        text.enableWordWrapping = attr.Wrapping;
        text.rectTransform.sizeDelta = new Vector2(Mathf.Min(width, attr.Size.Width), attr.Size.Height);
        text.rectTransform.anchorMin = new Vector2(0.5f, 0.5f);
        text.rectTransform.anchorMax = new Vector2(0.5f, 0.5f);
        text.rectTransform.pivot = new Vector2(0.5f, 0.5f);

        if (attr.Font?.FontAsset != null)
        {
            text.font = attr.Font.FontAsset;
            if (attr.Font.FontMaterial != null)
                text.fontMaterial = attr.Font.FontMaterial;
        }
    }

    public override GameObject? Instantiate(Size size, out Size actualSize)
    {
        if (Text == null)
        {
            actualSize = Size.Zero;
            return null;
        }

        var text = Object.Instantiate(VanillaAsset.StandardTextPrefab, null);
        text.transform.localPosition = Vector3.zero;

        ReflectAttribute(Attr, text, size.Width);
        text.text = Text.GetString();
        text.sortingOrder = 10;
        text.ForceMeshUpdate();

        if (Attr.IsFlexible)
        {
            if (text.enableWordWrapping)
            {
                float w = Mathf.Min(text.rectTransform.sizeDelta.x, text.textBounds.size.x);
                float h = text.textBounds.size.y;
                text.rectTransform.sizeDelta = new Vector2(w, h);
            }
            else
            {
                float pw = Mathf.Min(text.rectTransform.sizeDelta.x, text.preferredWidth);
                float ph = Mathf.Min(text.rectTransform.sizeDelta.y, text.preferredHeight);
                text.rectTransform.sizeDelta = new Vector2(pw, ph);
            }
            text.ForceMeshUpdate();
        }

        PostBuilder?.Invoke(text);

        actualSize = new Size(text.rectTransform.sizeDelta);
        return text.gameObject;
    }
}

// =====================================================================
// GUIButton — 按钮 Widget（SpriteRenderer 背景 + TextMeshPro 文本）
// =====================================================================

public class GUIButton : NoSGUIText
{
    public GUIClickAction? OnClick { get; init; }
    public GUIClickAction? OnRightClick { get; init; }
    public GUIClickAction? OnMouseOver { get; init; }
    public GUIClickAction? OnMouseOut { get; init; }
    public Color? ButtonColor { get; init; }
    public Color? SelectedColor { get; init; }
    public float? TextMargin { get; init; } = null;

    private float GetTextMargin() => TextMargin ?? 0.26f;

    public GUIButton(GUIAlignment alignment, TextAttribute attribute, TextComponent text) : base(alignment, attribute, text)
    {
        Attr = attribute;
    }

    public override GameObject? Instantiate(Size size, out Size actualSize)
    {
        var inner = base.Instantiate(size, out actualSize)!;

        var margin = GetTextMargin();

        // 按钮背景 SpriteRenderer
        var button = UnityHelper.CreateObject<SpriteRenderer>("Button", null, Vector3.zero, LayerExpansion.GetUILayer());
        button.sprite = VanillaAsset.TextButtonSprite;
        button.drawMode = SpriteDrawMode.Sliced;
        button.tileMode = SpriteTileMode.Continuous;
        button.size = actualSize.ToUnityVector() + new Vector2(margin * 0.84f, margin * 0.84f);

        // 文本放在按钮之上
        inner.transform.SetParent(button.transform);
        inner.transform.localPosition += new Vector3(0, 0, -0.05f);

        // 碰撞体
        var collider = button.gameObject.AddComponent<BoxCollider2D>();
        collider.size = actualSize.ToUnityVector() + new Vector2(margin * 0.6f, margin * 0.6f);
        collider.isTrigger = true;

        // PassiveButton
        var passiveButton = button.gameObject.SetUpButton(true, button, ButtonColor, SelectedColor);
        var clickable = new GUIClickable(passiveButton);

        if (OnClick != null)
            passiveButton.OnClick.AddListener(() => OnClick(clickable));
        if (OnMouseOver != null)
            passiveButton.OnMouseOver.AddListener(() => OnMouseOver(clickable));
        if (OnMouseOut != null)
            passiveButton.OnMouseOut.AddListener(() => OnMouseOut(clickable));

        actualSize.Width += margin + 0.1f;
        actualSize.Height += margin + 0.1f;

        return button.gameObject;
    }
}

// =====================================================================
// NoSGUIImage — 图片 Widget（SpriteRenderer）
// =====================================================================

public class NoSGUIImage : AbstractGUIWidget
{
    private readonly Sprite _sprite;
    private readonly FuzzySize _size;
    public Color? TintColor;
    public GUIClickAction? OnClick;
    public bool IsMasked;

    public NoSGUIImage(GUIAlignment alignment, Sprite sprite, FuzzySize size,
        Color? color = null, GUIClickAction? onClick = null, bool isMasked = true) : base(alignment)
    {
        _sprite = sprite;
        _size = size;
        TintColor = color;
        OnClick = onClick;
        IsMasked = isMasked;
    }

    public override GameObject? Instantiate(Size size, out Size actualSize)
    {
        if (_sprite == null)
        {
            actualSize = Size.Zero;
            return null;
        }

        var renderer = UnityHelper.CreateObject<SpriteRenderer>("Image", null, Vector3.zero, LayerExpansion.GetUILayer());
        renderer.sprite = _sprite;
        renderer.sortingOrder = 10;
        if (IsMasked) renderer.maskInteraction = SpriteMaskInteraction.VisibleInsideMask;

        var spriteSize = renderer.sprite.bounds.size;
        float scale = Mathf.Min(
            _size.Width.HasValue ? (_size.Width.Value / spriteSize.x) : float.MaxValue,
            _size.Height.HasValue ? (_size.Height.Value / spriteSize.y) : float.MaxValue
        );
        renderer.transform.localScale = Vector3.one * scale;

        if (TintColor != null) renderer.color = TintColor.Value.ToUnityColor();

        actualSize = new Size(spriteSize.x * scale, spriteSize.y * scale);

        if (OnClick != null)
        {
            var button = renderer.gameObject.SetUpButton(true, renderer, TintColor ?? Color.White);
            var collider = renderer.gameObject.AddComponent<BoxCollider2D>();
            collider.size = renderer.sprite.bounds.size;
            collider.isTrigger = true;

            var clickable = new GUIClickable(button);
            button.OnClick.AddListener(() => { OnClick.Invoke(clickable); });
        }

        return renderer.gameObject;
    }
}

// =====================================================================
// WidgetsHolder / VerticalWidgetsHolder / HorizontalWidgetsHolder
// =====================================================================

public abstract class WidgetsHolder : AbstractGUIWidget
{
    protected IEnumerable<GUIWidget> Widgets;

    protected WidgetsHolder(GUIAlignment alignment, IEnumerable<GUIWidget?> widgets) : base(alignment)
    {
        Widgets = widgets.Where(w => w != null)!;
    }
}

public class VerticalWidgetsHolder : WidgetsHolder
{
    public float? FixedWidth { get; init; } = null;

    public VerticalWidgetsHolder(GUIAlignment alignment, IEnumerable<GUIWidget?> widgets) : base(alignment, widgets) { }
    public VerticalWidgetsHolder(GUIAlignment alignment, params GUIWidget?[] widgets) : base(alignment, widgets) { }

    public override GameObject? Instantiate(Size size, out Size actualSize)
    {
        var results = Widgets.Select(c => (c.Instantiate(size, out var acSize), acSize, c)).ToArray();

        float maxWidth = 0f;
        float sumHeight = 0f;
        float? tempHeight = null;

        foreach (var r in results)
        {
            maxWidth = Mathf.Max(maxWidth, r.acSize.Width);
            if (r.c.PostponesConsideringSize)
            {
                tempHeight = Mathf.Max(tempHeight ?? r.acSize.Height, r.acSize.Height);
            }
            else
            {
                sumHeight += Mathf.Max(r.acSize.Height, tempHeight ?? r.acSize.Height);
                tempHeight = 0f;
            }
        }

        if (FixedWidth != null) maxWidth = FixedWidth.Value;

        var myObj = UnityHelper.CreateObject("WidgetsHolder", null, Vector3.zero, LayerExpansion.GetUILayer());

        float height = sumHeight * 0.5f;
        float? maxHeight = null;

        foreach (var r in results)
        {
            if (r.Item1 != null)
            {
                r.Item1.transform.SetParent(myObj.transform);
                r.Item1.transform.localPosition = new Vector3(
                    CalcWidth(r.c.Alignment, r.acSize.Width, maxWidth),
                    height - r.acSize.Height * 0.5f,
                    0f);
            }

            if (r.c.PostponesConsideringSize)
            {
                maxHeight = Mathf.Max(maxHeight ?? r.acSize.Height, r.acSize.Height);
            }
            else
            {
                height -= Mathf.Max(maxHeight ?? r.acSize.Height, r.acSize.Height);
                maxHeight = null;
            }
        }

        actualSize = new Size(maxWidth, sumHeight);
        return myObj;
    }
}

public class HorizontalWidgetsHolder : WidgetsHolder
{
    public float? FixedHeight { get; init; } = null;

    public HorizontalWidgetsHolder(GUIAlignment alignment, IEnumerable<GUIWidget?> widgets) : base(alignment, widgets) { }
    public HorizontalWidgetsHolder(GUIAlignment alignment, params GUIWidget?[] widgets) : base(alignment, widgets) { }

    public override GameObject? Instantiate(Size size, out Size actualSize)
    {
        var results = Widgets.Select(c => (c.Instantiate(size, out var acSize), acSize, c)).ToArray();

        float sumWidth = 0f;
        float maxHeight = 0f;
        float? tempWidth = null;

        foreach (var r in results)
        {
            maxHeight = Mathf.Max(maxHeight, r.acSize.Height);
            if (r.c.PostponesConsideringSize)
            {
                tempWidth = Mathf.Max(tempWidth ?? r.acSize.Width, r.acSize.Width);
            }
            else
            {
                sumWidth += Mathf.Max(r.acSize.Width, tempWidth ?? r.acSize.Width);
                tempWidth = 0f;
            }
        }

        if (FixedHeight != null) maxHeight = FixedHeight.Value;

        var myObj = UnityHelper.CreateObject("WidgetsHolder", null, Vector3.zero, LayerExpansion.GetUILayer());

        float width = -sumWidth * 0.5f;
        float? maxWidth = null;

        foreach (var r in results)
        {
            if (r.Item1 != null)
            {
                r.Item1.transform.SetParent(myObj.transform);
                r.Item1.transform.localPosition = new Vector3(
                    width + r.acSize.Width * 0.5f,
                    CalcHeight(r.c.Alignment, r.acSize.Height, maxHeight),
                    0f);
            }

            if (r.c.PostponesConsideringSize)
            {
                maxWidth = Mathf.Max(maxWidth ?? r.acSize.Width, r.acSize.Width);
            }
            else
            {
                width += Mathf.Max(maxWidth ?? r.acSize.Width, r.acSize.Width);
                maxWidth = null;
            }
        }

        actualSize = new Size(sumWidth, maxHeight);
        return myObj;
    }
}

using LightInDark.Core;
using TMPro;
using UnityEngine;
using UnityEngine.Events;
using UnityEngine.UI;
using Button = UnityEngine.UI.Button;
using Object = UnityEngine.Object;

namespace LightInDark.UI.Window;

/// <summary>
/// GUI 屏幕，基于 SpriteRenderer 体系。
/// 已通过 ClassInjector 注册为 Il2Cpp 类型。
/// </summary>
public class MetaScreen : MonoBehaviour, IGUIScreen
{
    private GameObject? _root;
    private GameObject? _screen;
    private GameObject? _background;
    private GameObject? _closeButton;
    private GameObject? _blackScreen;
    private Size _screenSize;

    /// <summary>
    /// 生成一个完整的窗口
    /// </summary>
    public static MetaScreen GenerateWindow(
        Vector2 size,
        Transform parent,
        Vector3 localPosition,
        bool withCloseButton = true,
        bool withBlackScreen = true)
    {
        var root = new GameObject("MetaWindow");
        root.layer = LayerExpansion.GetUILayer();
        root.transform.SetParent(parent, false);
        root.transform.localPosition = localPosition;
        root.transform.localScale = Vector3.one;

        // 黑色遮罩
        GameObject? blackScreen = null;
        if (withBlackScreen)
        {
            blackScreen = new GameObject("BlackScreen");
            blackScreen.layer = LayerExpansion.GetUILayer();
            blackScreen.transform.SetParent(root.transform, false);
            blackScreen.transform.localPosition = new Vector3(0f, 0f, 1f);
            var blackRenderer = blackScreen.AddComponent<SpriteRenderer>();
            blackRenderer.sprite = VanillaAsset.FullScreenSprite;
            blackRenderer.drawMode = SpriteDrawMode.Sliced;
            blackRenderer.size = new Vector2(30f, 30f);
            blackRenderer.color = new UColor(0f, 0f, 0f, 0.35f);
            blackRenderer.sortingOrder = 50;
        }

        // 窗口背景
        var bgObj = new GameObject("WindowBackground");
        bgObj.layer = LayerExpansion.GetUILayer();
        bgObj.transform.SetParent(root.transform, false);
        bgObj.transform.localPosition = Vector3.zero;
        var bgRenderer = bgObj.AddComponent<SpriteRenderer>();
        bgRenderer.sprite = VanillaAsset.PopUpBackSprite;
        bgRenderer.drawMode = SpriteDrawMode.Sliced;
        bgRenderer.size = size;
        bgRenderer.color = new UColor(1f, 1f, 1f, 0.8f);
        bgRenderer.sortingOrder = 51;

        // 内容屏幕
        var screenObj = new GameObject("Screen");
        screenObj.layer = LayerExpansion.GetUILayer();
        screenObj.transform.SetParent(bgObj.transform, false);
        screenObj.transform.localPosition = new Vector3(0f, 0f, -1f);
        var screen = screenObj.AddComponent<MetaScreen>();
        screen._root = root;
        screen._screen = screenObj;
        screen._background = bgObj;
        screen._blackScreen = blackScreen;
        screen._screenSize = new Size(size);

        // 关闭按钮
        if (withCloseButton)
        {
            screen._closeButton = CreateCloseButton(root.transform, new Vector3(size.x * 0.5f - 0.3f, size.y * 0.5f - 0.3f, -10f), screen);
        }

        return screen;
    }

    /// <summary>
    /// 生成透明窗口
    /// </summary>
    public static MetaScreen GenerateBlankWindow(Vector2 size, Transform parent, Vector3 localPosition)
    {
        var root = new GameObject("MetaWindow");
        root.layer = LayerExpansion.GetUILayer();
        root.transform.SetParent(parent, false);
        root.transform.localPosition = localPosition;
        root.transform.localScale = Vector3.one;

        var screenObj = new GameObject("Screen");
        screenObj.layer = LayerExpansion.GetUILayer();
        screenObj.transform.SetParent(root.transform, false);
        screenObj.transform.localPosition = Vector3.zero;
        var screen = screenObj.AddComponent<MetaScreen>();
        screen._root = root;
        screen._screen = screenObj;
        screen._screenSize = new Size(size);

        return screen;
    }

    /// <summary>
    /// 设置屏幕上显示的 Widget
    /// </summary>
    public void SetWidget(GUIWidget? widget, out Size actualSize)
    {
        // 清除已有内容
        for (int i = transform.childCount - 1; i >= 0; i--)
        {
            Object.Destroy(transform.GetChild(i).gameObject);
        }

        if (widget == null)
        {
            actualSize = Size.Zero;
            return;
        }

        var obj = widget.Instantiate(new Size(100f, 100f), out actualSize);
        if (obj != null)
        {
            obj.transform.SetParent(transform, false);
            obj.transform.localPosition = Vector3.zero;
        }
    }

    /// <summary>
    /// 关闭并销毁窗口
    /// </summary>
    public void Close()
    {
        if (_root != null)
        {
            Object.Destroy(_root);
            _root = null;
        }
    }

    void OnDestroy()
    {
        if (_root != null)
        {
            Object.Destroy(_root);
            _root = null;
        }
    }

    /// <summary>
    /// 创建关闭按钮
    /// </summary>
    private static GameObject CreateCloseButton(Transform parent, Vector3 localPos, MetaScreen screen)
    {
        var obj = new GameObject("CloseButton");
        obj.layer = LayerExpansion.GetUILayer();
        obj.transform.SetParent(parent, false);
        obj.transform.localPosition = localPos;
        obj.transform.localScale = Vector3.one;

        var btnSize = 0.4f;
        var renderer = obj.AddComponent<SpriteRenderer>();
        renderer.sprite = VanillaAsset.CloseButtonSprite;
        renderer.drawMode = SpriteDrawMode.Sliced;
        renderer.size = new Vector2(btnSize, btnSize);
        renderer.color = new UColor(0.8f, 0.2f, 0.2f, 1f);
        renderer.sortingOrder = 53;

        var collider = obj.AddComponent<BoxCollider2D>();
        collider.size = new Vector2(btnSize, btnSize);
        collider.isTrigger = true;

        var button = obj.AddComponent<PassiveButton>();
        button.OnMouseOver = new UnityEvent();
        button.OnMouseOut = new UnityEvent();
        button.OnClick = new Button.ButtonClickedEvent();
        button.OnClick.AddListener(() => screen.Close());
        button.OnMouseOver.AddListener(() => { renderer.color = new UColor(1f, 0.4f, 0.4f, 1f); });
        button.OnMouseOut.AddListener(() => { renderer.color = new UColor(0.8f, 0.2f, 0.2f, 1f); });

        return obj;
    }

    /// <summary>
    /// 快捷创建文本窗口（兼容现有调用）
    /// </summary>
    public static MetaScreen CreateWindow(string text)
    {
        var parent = HudManager.Instance != null ? HudManager.Instance.transform : null;
        if (parent == null)
        {
            LightLogger.LogWarning("[MetaScreen] HudManager 未就绪");
            return null!;
        }

        var gui = LIDGUI.Instance;
        var content = gui.VerticalHolder(
            GUIAlignment.Center,
            gui.RawText(GUIAlignment.Center, gui.GetAttribute(AttributeAsset.DocumentTitle), text),
            gui.VerticalMargin(0.3f),
            gui.RawButton(GUIAlignment.Center, gui.GetAttribute(AttributeAsset.CenteredBold), "关闭", _ => { })
        );

        var screen = GenerateWindow(new Vector2(4f, 1.5f), parent, new Vector3(0f, 0f, -50f));
        screen.SetWidget(content, out _);
        return screen;
    }

    /// <summary>
    /// 快捷创建带标题和内容的窗口
    /// </summary>
    public static MetaScreen CreateWindow(string title, GUIWidget content)
    {
        var parent = HudManager.Instance != null ? HudManager.Instance.transform : null;
        if (parent == null)
        {
            LightLogger.LogWarning("[MetaScreen] HudManager 未就绪");
            return null!;
        }

        var gui = LIDGUI.Instance;
        var fullContent = gui.VerticalHolder(
            GUIAlignment.Center,
            gui.RawText(GUIAlignment.Center, gui.GetAttribute(AttributeAsset.DocumentTitle), title),
            gui.VerticalMargin(0.2f),
            content
        );

        var screen = GenerateWindow(new Vector2(5f, 3f), parent, new Vector3(0f, 0f, -50f));
        screen.SetWidget(fullContent, out _);
        return screen;
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using UnityEngine;

namespace LightInDark.UI.Window;

/// <summary>
/// GUI 工厂实现，对应 Nebula 的 NebulaGUIWidgetEngine
/// </summary>
public class LIDGUI : IGUI
{
    public static LIDGUI Instance { get; } = new();

    private readonly Dictionary<AttributeParams, TextAttribute> _allAttr = new();
    private readonly Dictionary<AttributeAsset, TextAttribute> _allAttrAsset = new();

    public GUIWidget EmptyWidget => GUIEmptyWidget.Default;

    public GUIWidget Text(GUIAlignment alignment, TextAttribute attribute, TextComponent text)
        => new NoSGUIText(alignment, attribute, text);

    public GUIWidget RealtimeText(GUIAlignment alignment, TextAttribute attribute, Func<string> textSupplier, float width)
    {
        var widget = new NoSGUIText(alignment, attribute, new RawTextComponent(""))
        {
            PostBuilder = text =>
            {
                text.text = textSupplier();
                text.ForceMeshUpdate();
                text.gameObject.AddComponent<RealtimeTextBehaviour>().TMP = text;
                text.gameObject.GetComponent<RealtimeTextBehaviour>().Supplier = textSupplier;
            }
        };
        return widget;
    }

    public GUIWidget Button(GUIAlignment alignment, TextAttribute attribute, TextComponent text, GUIClickAction onClick,
        GUIClickAction? onMouseOver = null, GUIClickAction? onMouseOut = null, GUIClickAction? onRightClick = null,
        Color? color = null, Color? selectedColor = null, float? margin = null)
        => new GUIButton(alignment, attribute, text)
        {
            OnClick = onClick,
            OnMouseOver = onMouseOver,
            OnMouseOut = onMouseOut,
            OnRightClick = onRightClick,
            ButtonColor = color,
            SelectedColor = selectedColor,
            TextMargin = margin
        };

    public GUIWidget Image(GUIAlignment alignment, Sprite sprite, FuzzySize size, GUIClickAction? onClick = null, GUIWidgetSupplier? overlay = null, bool isMasked = true)
        => new NoSGUIImage(alignment, sprite, size, null, onClick, isMasked);

    public GUIWidget VerticalHolder(GUIAlignment alignment, IEnumerable<GUIWidget?> widgets, float? fixedWidth = null)
        => new VerticalWidgetsHolder(alignment, widgets) { FixedWidth = fixedWidth };

    public GUIWidget HorizontalHolder(GUIAlignment alignment, IEnumerable<GUIWidget?> widgets, float? fixedHeight = null)
        => new HorizontalWidgetsHolder(alignment, widgets) { FixedHeight = fixedHeight };

    public GUIWidget Arrange(GUIAlignment alignment, IEnumerable<GUIWidget?> widgets, int perLine)
    {
        var rows = new List<GUIWidget>();
        var current = new List<GUIWidget>();

        foreach (var w in widgets)
        {
            if (w == null) continue;
            current.Add(w);
            if (current.Count == perLine)
            {
                rows.Add(HorizontalHolder(alignment, current.ToArray()));
                current.Clear();
            }
        }
        if (current.Count > 0)
            rows.Add(HorizontalHolder(alignment, current.ToArray()));

        return VerticalHolder(alignment, rows.ToArray());
    }

    public GUIWidget Margin(FuzzySize margin)
        => new NoSGUIMargin(GUIAlignment.Center, new Vector2(margin.Width ?? 0f, margin.Height ?? 0f));

    public TextAttribute GetAttribute(AttributeAsset attribute)
    {
        if (_allAttrAsset.TryGetValue(attribute, out var attr))
            return attr;

