    public TextAttribute GenerateAttribute(AttributeParams param, Color color, FontSize fontSize, Size size)
    {
        var flag = (AttributeTemplateFlag)(int)param;

        TextAlignment alignment = (flag & AttributeTemplateFlag.AlignmentMask) switch
        {
            AttributeTemplateFlag.AlignmentLeft => TextAlignment.Left,
            AttributeTemplateFlag.AlignmentRight => TextAlignment.Right,
            _ => TextAlignment.Center
        };

        FontAsset fontAsset = (flag & (AttributeTemplateFlag.FontMask | AttributeTemplateFlag.MaterialMask)) switch
        {
            AttributeTemplateFlag.FontStandard | AttributeTemplateFlag.MaterialBared => FontAsset.Gothic,
            AttributeTemplateFlag.FontStandard => FontAsset.GothicMasked,
            AttributeTemplateFlag.FontOblong | AttributeTemplateFlag.MaterialBared => FontAsset.Oblong,
            AttributeTemplateFlag.FontOblong => FontAsset.OblongMasked,
            AttributeTemplateFlag.FontBarlow | AttributeTemplateFlag.MaterialBared => FontAsset.Barlow,
            AttributeTemplateFlag.FontBarlow => FontAsset.Barlow,
            _ => FontAsset.GothicMasked,
        };

        FontStyle style = 0;
        if ((flag & AttributeTemplateFlag.StyleBold) != 0) style |= FontStyle.Bold;

        bool isFlexible = (flag & AttributeTemplateFlag.IsFlexible) != 0;

        return new TextAttribute(alignment, GetFont(fontAsset), style, fontSize, size, color, isFlexible);
    }

    public Font GetFont(FontAsset fontAsset)
    {
        return fontAsset switch
        {
            FontAsset.Prespawn => new Font { FontAsset = VanillaAsset.PreSpawnFont, IsMasked = false },
            FontAsset.Barlow => new Font { FontAsset = VanillaAsset.VersionFont, IsMasked = false },
            FontAsset.Gothic => new Font { FontAsset = VanillaAsset.StandardTextPrefab?.font, IsMasked = false },
            FontAsset.GothicMasked => new Font { FontAsset = VanillaAsset.StandardTextPrefab?.font, FontMaterial = VanillaAsset.StandardMaskedFontMaterial, IsMasked = true },
            FontAsset.Oblong => new Font { FontAsset = VanillaAsset.BrookFont, IsMasked = false },
            FontAsset.OblongMasked => new Font { FontAsset = VanillaAsset.BrookFont, FontMaterial = VanillaAsset.StandardMaskedFontMaterial, IsMasked = true },
            _ => new Font { FontAsset = VanillaAsset.StandardTextPrefab?.font, IsMasked = false },
        };
    }

    public TextComponent RawTextComponent(string rawText) => new RawTextComponent(rawText);
    public TextComponent TranslateTextComponent(string translationKey) => new TranslateTextComponent(translationKey);
    public TextComponent ColorTextComponent(Color color, TextComponent component) => new ColorTextComponent(color, component);
}

/// <summary>
/// 实时文本更新组件
/// </summary>
public class RealtimeTextBehaviour : MonoBehaviour
{
    public TextMeshPro? TMP;
    public Func<string>? Supplier;
    private string? _lastText;

    public void Update()
    {
        if (TMP == null || Supplier == null) return;
        var current = Supplier();
        if (current != _lastText)
        {
            _lastText = current;
            TMP.text = current;
            TMP.ForceMeshUpdate();
        }
    }
}

using System;
using System.Collections.Generic;
using UnityEngine;

namespace LightInDark.UI.Window;

/// <summary>
/// 高级 UI 辅助类，对应 Nebula 的 MetaUI / MetaDialog
/// </summary>
public static class MetaUI
{
    /// <summary>
    /// 按钮窗口选项
    /// </summary>
    public readonly struct ButtonOption
    {
        public readonly string Label;
        public readonly Action OnClick;
        public readonly Color? Color;

        public ButtonOption(string label, Action onClick, Color? color = null)
        {
            Label = label;
            OnClick = onClick;
            Color = color;
        }
    }

    /// <summary>
    /// 打开一个按钮选择窗口
    /// </summary>
    public static MetaScreen OpenButtonWindow(string title, params ButtonOption[] options)
    {
        var gui = LIDGUI.Instance;
        var attr = gui.GetAttribute(AttributeAsset.CenteredBold);
        var widgets = new List<GUIWidget?>();

        widgets.Add(gui.RawText(GUIAlignment.Center, gui.GetAttribute(AttributeAsset.DocumentTitle), title));
        widgets.Add(gui.VerticalMargin(0.3f));

        foreach (var opt in options)
        {
            var localOpt = opt;
            widgets.Add(gui.RawButton(
                GUIAlignment.Center,
                attr,
                localOpt.Label,
                clickable => { localOpt.OnClick?.Invoke(); },
                color: localOpt.Color
            ));
            widgets.Add(gui.VerticalMargin(0.1f));
        }

        widgets.Add(gui.VerticalMargin(0.2f));
        widgets.Add(gui.RawButton(
            GUIAlignment.Center,
            gui.GetAttribute(AttributeAsset.DocumentStandard),
            "关闭",
            clickable => { },
            color: Color.Gray
        ));

        var content = gui.VerticalHolder(GUIAlignment.Center, widgets.ToArray());

        var screen = MetaScreen.GenerateWindow(
            new Vector2(4.5f, 3f),
            GetParent(),
            new Vector3(0f, 0f, -50f),
            withCloseButton: true,
            withBlackScreen: true
        );

        screen.SetWidget(content, out _);
        return screen;
    }

    /// <summary>
    /// 打开一个确认对话框（是/否）
    /// </summary>
    public static MetaScreen OpenConfirmDialog(string message, Action onConfirm, Action? onCancel = null)
    {
        var gui = LIDGUI.Instance;
        var attr = gui.GetAttribute(AttributeAsset.CenteredBold);
        var localOnCancel = onCancel;

        var content = gui.VerticalHolder(
            GUIAlignment.Center,
            gui.RawText(GUIAlignment.Center, attr, message),
            gui.VerticalMargin(0.3f),
            gui.HorizontalHolder(
                GUIAlignment.Center,
                gui.RawButton(GUIAlignment.Center, attr, "是",
                    clickable => { onConfirm?.Invoke(); }, color: Color.Green),
                gui.HorizontalMargin(0.3f),
                gui.RawButton(GUIAlignment.Center, attr, "否",
                    clickable => { localOnCancel?.Invoke(); }, color: Color.Red)
            )
        );

        var screen = MetaScreen.GenerateWindow(
            new Vector2(3.9f, 1.5f),
            GetParent(),
            new Vector3(0f, 0f, -50f),
            withCloseButton: false,
            withBlackScreen: true
        );

        screen.SetWidget(content, out _);
        return screen;
    }

    /// <summary>
    /// 打开一个消息对话框（仅含"确定"按钮）
    /// </summary>
    public static MetaScreen OpenMessageDialog(string message, Action? onClose = null)
    {
        var gui = LIDGUI.Instance;
        var attr = gui.GetAttribute(AttributeAsset.CenteredBold);
        var localOnClose = onClose;

        var content = gui.VerticalHolder(
            GUIAlignment.Center,
            gui.RawText(GUIAlignment.Center, attr, message),
            gui.VerticalMargin(0.3f),
            gui.RawButton(GUIAlignment.Center, attr, "确定",
                clickable => { localOnClose?.Invoke(); })
        );

        var screen = MetaScreen.GenerateWindow(
            new Vector2(3.5f, 1.5f),
            GetParent(),
            new Vector3(0f, 0f, -50f),
            withCloseButton: false,
            withBlackScreen: true
        );

        screen.SetWidget(content, out _);
        return screen;
    }

    /// <summary>
    /// 打开一个文本展示窗口（带标题）
    /// </summary>
    public static MetaScreen OpenTextWindow(string title, string text)
    {
        var gui = LIDGUI.Instance;

        var content = gui.VerticalHolder(
            GUIAlignment.Center,
            gui.RawText(GUIAlignment.Center, gui.GetAttribute(AttributeAsset.DocumentTitle), title),
            gui.VerticalMargin(0.2f),
            gui.RawText(GUIAlignment.Left, gui.GetAttribute(AttributeAsset.DocumentStandard), text)
        );

        var screen = MetaScreen.GenerateWindow(
            new Vector2(5f, 3f),
            GetParent(),
            new Vector3(0f, 0f, -50f),
            withCloseButton: true,
            withBlackScreen: true
        );

        screen.SetWidget(content, out _);
        return screen;
    }

    /// <summary>
    /// 打开一个自定义内容窗口
    /// </summary>
    public static MetaScreen OpenCustomWindow(string title, GUIWidget contentWidget, Vector2? windowSize = null)
    {
        var gui = LIDGUI.Instance;

        var content = gui.VerticalHolder(
            GUIAlignment.Center,
            gui.RawText(GUIAlignment.Center, gui.GetAttribute(AttributeAsset.DocumentTitle), title),
            gui.VerticalMargin(0.2f),
            contentWidget
        );

        var screen = MetaScreen.GenerateWindow(
            windowSize ?? new Vector2(5f, 3f),
            GetParent(),
            new Vector3(0f, 0f, -50f),
            withCloseButton: true,
            withBlackScreen: true
        );

        screen.SetWidget(content, out _);
        return screen;
    }

    private static Transform GetParent()
    {
        if (HudManager.Instance != null)
            return HudManager.Instance.transform;

        var go = new GameObject("MetaUI_TempParent");
        UnityEngine.Object.DontDestroyOnLoad(go);
        return go.transform;
    }
}

using UnityEngine;

namespace LightInDark.UI.Window;

/// <summary>
/// Widget 扩展方法，对应 Nebula 的 GUIWidgetHelpers
/// </summary>
public static class GUIWidgetHelpers
{
    public static GUIWidget WithRoom(this GUIWidget inner, Vector2 margin)
    {
        var gui = LIDGUI.Instance;

        if (margin.x > 0f)
        {
            var xMargin = gui.HorizontalMargin(margin.x * 0.5f);
            inner = gui.HorizontalHolder(inner.Alignment, xMargin, inner, xMargin);
        }
        if (margin.y > 0f)
        {
            var yMargin = gui.VerticalMargin(margin.y * 0.5f);
            inner = gui.VerticalHolder(inner.Alignment, yMargin, inner, yMargin);
        }
        return inner;
    }

    public static GUIWidget Move(this GUIWidget inner, Vector2 diff)
    {
        var gui = LIDGUI.Instance;

        if (diff.x > 0f)
            inner = gui.HorizontalHolder(inner.Alignment, gui.HorizontalMargin(diff.x), inner);
        if (diff.x < 0f)
            inner = gui.HorizontalHolder(inner.Alignment, inner, gui.HorizontalMargin(-diff.x));

        if (diff.y > 0f)
            inner = gui.VerticalHolder(inner.Alignment, gui.VerticalMargin(diff.y), inner);
        if (diff.y < 0f)
            inner = gui.VerticalHolder(inner.Alignment, inner, gui.VerticalMargin(-diff.y));

        return inner;
    }

    public static GUIWidget FixSize(this GUIWidget inner, Size size)
        => new GUISizeFixer(inner, size);

    public static GUIWidget WithLogic(this GUIWidget inner, System.Action<GameObject?, Size> logic)
        => new LogicGUIWidget(inner, logic);
}

