using System;
using System.Collections.Generic;
using TMPro;
using UnityEngine;
using UnityEngine.Events;
using UnityEngine.UI;
using Button = UnityEngine.UI.Button;
using Object = UnityEngine.Object;

namespace LightInDark.UI.HudUI;

/// <summary>
/// 基于原版 Among Us DialogueBox 克隆的窗口。
/// 直接复用游戏原生 UI 组件，外观与原版一致。
/// </summary>
public class HudUIWindow
{
    /// <summary>克隆的 DialogueBox 组件</summary>
    public DialogueBox Dialogue { get; private set; }

    /// <summary>窗口根 GameObject</summary>
    public GameObject GameObject { get; private set; }

    /// <summary>内容容器（Dialogue 的 target 父级）</summary>
    private readonly List<GameObject> _contentObjects = new();

    private HudUIWindow(DialogueBox dialogue)
    {
        Dialogue = dialogue;
        GameObject = dialogue.gameObject;
    }

    /// <summary>
    /// 创建一个窗口（克隆原版 DialogueBox）
    /// </summary>
    /// <param name="title">窗口标题</param>
    /// <param name="parent">父级 Transform（默认为 HudManager）</param>
    public static HudUIWindow Create(string title = "", Transform? parent = null)
    {
        if (HudManager.Instance == null || HudManager.Instance.Dialogue == null)
            throw new InvalidOperationException("HudManager 或 Dialogue 未就绪");

        parent ??= HudManager.Instance.transform;

        var dialogue = Object.Instantiate(HudManager.Instance.Dialogue, parent);
        dialogue.name = "HudUIWindow";
        dialogue.transform.localPosition = new Vector3(0f, 0f, -50f);

        var window = new HudUIWindow(dialogue);
        window.Show(title);
        return window;
    }

    /// <summary>
    /// 显示窗口
    /// </summary>
    public void Show(string title = "")
    {
        Dialogue.Show(title);
    }

    /// <summary>
    /// 关闭并销毁窗口
    /// </summary>
    public void Close()
    {
        ClearContent();
        Dialogue.Hide();
        Object.Destroy(GameObject);
    }

    /// <summary>
    /// 清空窗口内容（保留 DialogueBox 框架）
    /// </summary>
    public void ClearContent()
    {
        foreach (var obj in _contentObjects)
        {
            if (obj != null) Object.Destroy(obj);
        }
        _contentObjects.Clear();
    }

    /// <summary>
    /// 设置窗口标题
    /// </summary>
    public void SetTitle(string title)
    {
        Dialogue.target.text = title;
    }

    /// <summary>
    /// 在窗口中添加文本行
    /// </summary>
    public TextMeshPro AddText(string text, float fontSize = 1.5f,
        TextAlignmentOptions alignment = TextAlignmentOptions.Center)
    {
        var tmp = Object.Instantiate(HudManager.Instance.Dialogue.target, Dialogue.transform);
        tmp.transform.localPosition = new Vector3(0f, GetNextY(), -1f);
        tmp.text = text;
        tmp.fontSize = fontSize;
        tmp.alignment = alignment;
        tmp.ForceMeshUpdate();

        _contentObjects.Add(tmp.gameObject);
        return tmp;
    }

    /// <summary>
    /// 在窗口中添加按钮（克隆原版 KillButton 的按钮结构）
    /// </summary>
    public PassiveButton AddButton(string text, Action onClick, Color? color = null)
    {
        var hudMgr = HudManager.Instance;
        if (hudMgr?.KillButton == null) return null!;

        // 克隆 KillButton 的按钮结构（SpriteRenderer + TextMeshPro + BoxCollider2D + PassiveButton）
        var buttonObj = new GameObject("HudUIButton");
        buttonObj.layer = LayerMask.NameToLayer("UI");
        buttonObj.transform.SetParent(Dialogue.transform, false);
        buttonObj.transform.localPosition = new Vector3(0f, GetNextY(), -1f);

        // 背景 SpriteRenderer
        var renderer = buttonObj.AddComponent<SpriteRenderer>();
        renderer.sprite = hudMgr.KillButton.graphic.sprite;
        renderer.drawMode = SpriteDrawMode.Sliced;
        renderer.size = new Vector2(2.5f, 0.5f);
        renderer.color = color?.ToUnityColor() ?? UColor.white;
        renderer.sortingOrder = 52;

        // 碰撞体
        var collider = buttonObj.AddComponent<BoxCollider2D>();
        collider.size = new Vector2(2.5f, 0.5f);
        collider.isTrigger = true;

        // 文本
        var tmpObj = new GameObject("Text");
        tmpObj.layer = LayerMask.NameToLayer("UI");
        tmpObj.transform.SetParent(buttonObj.transform, false);
        tmpObj.transform.localPosition = new Vector3(0f, 0f, -0.1f);

        var tmp = Object.Instantiate(hudMgr.Dialogue.target, tmpObj.transform);
        tmp.transform.localPosition = Vector3.zero;
        tmp.text = text;
        tmp.fontSize = 2f;
        tmp.fontSizeMax = 2f;
        tmp.fontSizeMin = 1f;
        tmp.enableAutoSizing = true;
        tmp.alignment = TextAlignmentOptions.Center;
        tmp.color = UColor.white;
        tmp.rectTransform.sizeDelta = new Vector2(2.2f, 0.4f);
        tmp.rectTransform.pivot = new Vector2(0.5f, 0.5f);

        // PassiveButton 交互
        var button = buttonObj.AddComponent<PassiveButton>();
        button.OnMouseOver = new UnityEvent();
        button.OnMouseOut = new UnityEvent();
        button.OnClick = new Button.ButtonClickedEvent();

        var normalColor = color?.ToUnityColor() ?? UColor.white;
        var hoverColor = new UColor(0f, 1f, 42f / 255f, 1f);

        button.OnMouseOver.AddListener((UnityAction)(() =>
        {
            renderer.color = hoverColor;
            try { SoundManager.Instance.PlaySound(VanillaAsset.FindSoundClip("UI_Hover"), false, 0.8f); } catch { }
        }));
        button.OnMouseOut.AddListener((UnityAction)(() => { renderer.color = normalColor; }));

        var localOnClick = onClick;
        button.OnClick.AddListener((UnityAction)(() =>
        {
            try { SoundManager.Instance.PlaySound(VanillaAsset.FindSoundClip("UI_Select"), false, 0.8f); } catch { }
            localOnClick?.Invoke();
        }));

        _contentObjects.Add(buttonObj);
        return button;
    }

    /// <summary>
    /// 设置窗口大小
    /// </summary>
    public void SetSize(Vector2 size)
    {
        var renderer = GameObject.transform.GetChild(0).GetComponent<SpriteRenderer>();
        if (renderer != null)
        {
            renderer.size = size;
            var collider = renderer.GetComponent<BoxCollider2D>();
            if (collider != null) collider.size = size;
        }
        Dialogue.target.rectTransform.sizeDelta = size * 1.66f - new Vector2(0.7f, 0.7f);
    }

    /// <summary>
    /// 启用/禁用返回按钮
    /// </summary>
    public void SetBackButton(bool enabled)
    {
        if (Dialogue.BackButton != null)
            Dialogue.BackButton.gameObject.SetActive(enabled);
    }

    private float _currentY = 0f;

    private float GetNextY()
    {
        float y = _currentY;
        _currentY -= 0.6f;
        return y;
    }
}

/// <summary>
/// 基于原版 Among Us ActionButton 克隆的按钮。
/// 直接复用游戏原生 KillButton 结构，支持冷却、标签、图标。
/// </summary>
public class HudUIButton
{
    /// <summary>克隆的 GameObject</summary>
    public GameObject GameObject { get; private set; }

    /// <summary>ActionButton 组件</summary>
    public KillButton ActionButton { get; private set; }

    /// <summary>SpriteRenderer 图标</summary>
    public SpriteRenderer Graphic { get; private set; }

    /// <summary>标签文本</summary>
    public TextMeshPro LabelText { get; private set; }

    private HudUIButton(GameObject obj, KillButton button)
    {
        GameObject = obj;
        ActionButton = button;
        Graphic = button.graphic;
        LabelText = button.buttonLabelText;
    }

    /// <summary>
    /// 创建按钮（克隆原版 KillButton）
    /// </summary>
    /// <param name="parent">父级 Transform</param>
    /// <param name="label">按钮标签</param>
    /// <param name="sprite">按钮图标</param>
    public static HudUIButton Create(Transform parent, string label = "", Sprite? sprite = null)
    {
        if (HudManager.Instance?.KillButton == null)
            throw new InvalidOperationException("HudManager 或 KillButton 未就绪");

        var template = HudManager.Instance.KillButton;
        var obj = Object.Instantiate(template.gameObject, parent, false);
        obj.name = "HudUIButton";

        var button = obj.GetComponent<KillButton>();
        var hudButton = new HudUIButton(obj, button);

        if (!string.IsNullOrEmpty(label))
            hudButton.SetLabel(label);

        if (sprite != null)
            hudButton.SetSprite(sprite);

        button.SetCoolDown(0f, 1f);
        button.SetInfiniteUses();
        obj.SetActive(false);

        return hudButton;
    }

    /// <summary>设置标签</summary>
    public void SetLabel(string label)
    {
        if (LabelText != null)
            LabelText.text = label;
    }

    /// <summary>设置图标</summary>
    public void SetSprite(Sprite sprite)
    {
        if (Graphic != null)
            Graphic.sprite = sprite;
    }

    /// <summary>设置点击回调</summary>
    public void SetOnClick(Action onClick)
    {
        if (ActionButton == null) return;

        // KillButton 的 DoClick 会被游戏调用，我们需要用 PassiveButton 拦截
        var passiveButton = GameObject.GetComponent<PassiveButton>();
        if (passiveButton != null)
        {
            passiveButton.OnClick.RemoveAllListeners();
            passiveButton.OnClick.AddListener((UnityAction)(() => onClick?.Invoke()));
        }
    }

    /// <summary>设置可见性</summary>
    public void SetVisible(bool visible)
    {
        GameObject.SetActive(visible);
    }

    /// <summary>设置启用/禁用</summary>
    public void SetEnabled(bool enabled)
    {
        if (enabled)
            ActionButton?.SetEnabled();
        else
            ActionButton?.SetDisabled();
    }

    /// <summary>设置冷却</summary>
    public void SetCooldown(float current, float max)
    {
        ActionButton?.SetCoolDown(current, max);
    }

    /// <summary>设置位置</summary>
    public void SetPosition(Vector3 localPosition)
    {
        GameObject.transform.localPosition = localPosition;
    }

    /// <summary>销毁按钮</summary>
    public void Destroy()
    {
        Object.Destroy(GameObject);
    }
}

using System;
using System.Collections.Generic;
using TMPro;
using UnityEngine;

namespace LightInDark.UI.HudUI;

/// <summary>
/// HudUI 高级辅助方法，提供常用窗口的快捷创建。
/// 基于 DialogueBox 克隆实现，外观与原版一致。
/// </summary>
public static class HudUI
{
    /// <summary>
    /// 按钮窗口选项
    /// </summary>
    public readonly struct ButtonOption
    {
        public readonly string Label;
        public readonly Action OnClick;
        public readonly Color? Color;

        public ButtonOption(string label, Action onClick, Color? color = null)
        {
            Label = label;
            OnClick = onClick;
            Color = color;
        }
    }

    /// <summary>
    /// 打开一个按钮选择窗口
    /// </summary>
    public static HudUIWindow OpenButtonWindow(string title, params ButtonOption[] options)
    {
        var window = HudUIWindow.Create(title);
        window.SetBackButton(true);

        foreach (var opt in options)
        {
            var localOpt = opt;
            window.AddButton(localOpt.Label, () =>
            {
                localOpt.OnClick?.Invoke();
                window.Close();
            }, localOpt.Color);
        }

        return window;
    }

    /// <summary>
    /// 打开一个确认对话框（是/否）
    /// </summary>
    public static HudUIWindow OpenConfirmDialog(string message, Action onConfirm, Action? onCancel = null)
    {
        var window = HudUIWindow.Create("");
        window.SetBackButton(false);

        window.AddText(message, 1.5f, TextAlignmentOptions.Center);

        var confirmOpt = new ButtonOption("是", () =>
        {
            onConfirm?.Invoke();
            window.Close();
        }, Color.Green);

        var cancelOpt = new ButtonOption("否", () =>
        {
            onCancel?.Invoke();
            window.Close();
        }, Color.Red);

        // 在同一行放两个按钮（简化：先放"是"再放"否"）
        window.AddButton("是", () =>
        {
            onConfirm?.Invoke();
            window.Close();
        }, Color.Green);

        // 移除上一步添加的多余文本，用新按钮替换
        // 由于 DialogueBox 布局限制，这里简化为垂直排列
        window.AddButton("否", () =>
        {
            onCancel?.Invoke();
            window.Close();
        }, Color.Red);

        return window;
    }

    /// <summary>
    /// 打开一个消息对话框（仅含"确定"按钮）
    /// </summary>
    public static HudUIWindow OpenMessageDialog(string message, Action? onClose = null)
    {
        var window = HudUIWindow.Create("");
        window.SetBackButton(false);

        window.AddText(message, 1.5f, TextAlignmentOptions.Center);
        window.AddButton("确定", () =>
        {
            onClose?.Invoke();
            window.Close();
        });

        return window;
    }

    /// <summary>
    /// 打开一个文本展示窗口（带标题）
    /// </summary>
    public static HudUIWindow OpenTextWindow(string title, string text)
    {
        var window = HudUIWindow.Create(title);
        window.SetBackButton(true);
        window.AddText(text, 1.2f, TextAlignmentOptions.Left);
        return window;
    }

    /// <summary>
    /// 打开一个自定义内容窗口
    /// </summary>
    /// <param name="title">标题</param>
    /// <param name="builder">内容构建回调，通过 window 参数添加内容</param>
    public static HudUIWindow OpenCustomWindow(string title, Action<HudUIWindow> builder)
    {
        var window = HudUIWindow.Create(title);
        window.SetBackButton(true);
        builder?.Invoke(window);
        return window;
    }
}

