                "LightInDark.Resources.GUI.Background_Frame.png", 100f, 12, 12, 12, 12);
            return _frameSprite;
        }
    }

    // GUI/Background_Inner.png — 九宫格
    private static Sprite? _innerSprite;
    public static Sprite InnerSprite
