using System;
using TMPro;
using UnityEngine;
using UnityEngine.Events;
using UnityEngine.UI;
using Button = UnityEngine.UI.Button;
using Object = UnityEngine.Object;

namespace LightInDark.UI.HudUI;

/// <summary>
/// 按钮尺寸预设
/// </summary>
public static class ButtonSize
{
    /// <summary>正方形（0.8 × 0.8）</summary>
    public static readonly Vector2 Square = new(0.8f, 0.8f);

    /// <summary>长方形（2.5 × 0.5）</summary>
    public static readonly Vector2 Rectangle = new(2.5f, 0.5f);

    /// <summary>小正方形（0.4 × 0.4）</summary>
    public static readonly Vector2 SmallSquare = new(0.4f, 0.4f);

    /// <summary>长按钮（3.5 × 0.5）</summary>
    public static readonly Vector2 LongRectangle = new(3.5f, 0.5f);

    /// <summary>宽按钮（4.0 × 0.6）</summary>
    public static readonly Vector2 Wide = new(4.0f, 0.6f);
}

/// <summary>
/// 自定义按钮样式，使用精灵图材质。
/// 支持普通/悬停/选中三态切换。
/// </summary>
public class HudUIButton
{
    /// <summary>按钮 GameObject</summary>
    public GameObject GameObject { get; private set; }

    /// <summary>背景 SpriteRenderer</summary>
    public SpriteRenderer Renderer { get; private set; }

    /// <summary>文本组件</summary>
    public TextMeshPro Text { get; private set; }

    /// <summary>PassiveButton 交互组件</summary>
    public PassiveButton Button { get; private set; }

    /// <summary>碰撞体</summary>
    public BoxCollider2D Collider { get; private set; }

    private Sprite _normalSprite;
    private Sprite _hoverSprite;
    private Sprite _selectedSprite;
    private Sprite _selectedHoverSprite;
    private bool _isSelected;
    private Vector2 _size;

    private HudUIButton(GameObject obj)
    {
        GameObject = obj;
        Renderer = obj.GetComponent<SpriteRenderer>();
        Text = obj.GetComponentInChildren<TextMeshPro>();
        Button = obj.GetComponent<PassiveButton>();
        Collider = obj.GetComponent<BoxCollider2D>();
    }

    /// <summary>
    /// 创建现代风格按钮（使用 GUI/Button.png 精灵图）
    /// </summary>
    /// <param name="parent">父级 Transform</param>
    /// <param name="text">按钮文本</param>
    /// <param name="size">按钮尺寸（默认长方形）</param>
    /// <param name="onClick">点击回调</param>
    public static HudUIButton Create(Transform parent, string text = "",
        Vector2? size = null, Action? onClick = null)
    {
        var btnSize = size ?? ButtonSize.Rectangle;

        var obj = new GameObject("HudUIButton");
        obj.layer = LayerMask.NameToLayer("UI");
        obj.transform.SetParent(parent, false);
        obj.transform.localPosition = Vector3.zero;
        obj.transform.localScale = Vector3.one;

        // 背景 SpriteRenderer
        var renderer = obj.AddComponent<SpriteRenderer>();
        renderer.sprite = HudUIAssets.ButtonNormal;
        renderer.drawMode = SpriteDrawMode.Sliced;
        renderer.tileMode = SpriteTileMode.Continuous;
        renderer.size = btnSize;
        renderer.sortingOrder = 52;

        // 碰撞体
        var collider = obj.AddComponent<BoxCollider2D>();
        collider.size = btnSize;
        collider.isTrigger = true;

        // 文本
        var textObj = new GameObject("Text");
        textObj.layer = LayerMask.NameToLayer("UI");
        textObj.transform.SetParent(obj.transform, false);
        textObj.transform.localPosition = new Vector3(0f, 0f, -0.05f);

        var tmp = CreateText(textObj);
        tmp.text = text;
        tmp.fontSize = 2f;
        tmp.fontSizeMax = 2f;
        tmp.fontSizeMin = 1f;
        tmp.enableAutoSizing = true;
        tmp.alignment = TextAlignmentOptions.Center;
        tmp.color = UnityEngine.Color.white;
        tmp.rectTransform.sizeDelta = btnSize - new Vector2(0.2f, 0.15f);
        tmp.rectTransform.pivot = new Vector2(0.5f, 0.5f);
        tmp.ForceMeshUpdate();

        // PassiveButton
        var button = obj.AddComponent<PassiveButton>();
        button.OnMouseOver = new UnityEvent();
        button.OnMouseOut = new UnityEvent();
        button.OnClick = new Button.ButtonClickedEvent();

        var hudButton = new HudUIButton(obj);
        hudButton._normalSprite = HudUIAssets.ButtonNormal;
        hudButton._hoverSprite = HudUIAssets.ButtonHover;
        hudButton._selectedSprite = HudUIAssets.ButtonSelected;
        hudButton._selectedHoverSprite = HudUIAssets.ButtonSelectedHover;
        hudButton._size = btnSize;

        // 悬停/离开 事件
        button.OnMouseOver.AddListener((UnityAction)(() =>
        {
            renderer.sprite = hudButton._isSelected ? hudButton._selectedHoverSprite : hudButton._hoverSprite;
            try { SoundManager.Instance.PlaySound(LightInDark.UI.Window.VanillaAsset.FindSoundClip("UI_Hover"), false, 0.8f); } catch { }
        }));
        button.OnMouseOut.AddListener((UnityAction)(() =>
        {
            renderer.sprite = hudButton._isSelected ? hudButton._selectedSprite : hudButton._normalSprite;
        }));

        // 点击 事件
        var localOnClick = onClick;
        button.OnClick.AddListener((UnityAction)(() =>
        {
            try { SoundManager.Instance.PlaySound(LightInDark.UI.Window.VanillaAsset.FindSoundClip("UI_Select"), false, 0.8f); } catch { }
            localOnClick?.Invoke();
        }));

        return hudButton;
    }

    /// <summary>
    /// 创建简单颜色按钮（使用 ColorButton.png / ColorButtonSelected.png）
    /// </summary>
    public static HudUIButton CreateColorButton(Transform parent, string text = "",
        Vector2? size = null, Action? onClick = null, Color? color = null)
    {
        var btnSize = size ?? ButtonSize.Rectangle;
        var btnColor = color?.ToUnityColor() ?? UnityEngine.Color.white;

        var obj = new GameObject("HudUIColorButton");
        obj.layer = LayerMask.NameToLayer("UI");
        obj.transform.SetParent(parent, false);
        obj.transform.localPosition = Vector3.zero;
        obj.transform.localScale = Vector3.one;

        var renderer = obj.AddComponent<SpriteRenderer>();
        renderer.sprite = HudUIAssets.ColorButtonSprite;
        renderer.drawMode = SpriteDrawMode.Sliced;
        renderer.tileMode = SpriteTileMode.Continuous;
        renderer.size = btnSize;
        renderer.color = btnColor;
        renderer.sortingOrder = 52;

        var collider = obj.AddComponent<BoxCollider2D>();
        collider.size = btnSize;
        collider.isTrigger = true;

        // 文本
        var textObj = new GameObject("Text");
        textObj.layer = LayerMask.NameToLayer("UI");
        textObj.transform.SetParent(obj.transform, false);
        textObj.transform.localPosition = new Vector3(0f, 0f, -0.05f);

        var tmp = CreateText(textObj);
        tmp.text = text;
        tmp.fontSize = 2f;
        tmp.fontSizeMax = 2f;
        tmp.fontSizeMin = 1f;
        tmp.enableAutoSizing = true;
        tmp.alignment = TextAlignmentOptions.Center;
        tmp.color = UnityEngine.Color.white;
        tmp.rectTransform.sizeDelta = btnSize - new Vector2(0.2f, 0.15f);
        tmp.rectTransform.pivot = new Vector2(0.5f, 0.5f);
        tmp.ForceMeshUpdate();

        var button = obj.AddComponent<PassiveButton>();
        button.OnMouseOver = new UnityEvent();
        button.OnMouseOut = new UnityEvent();
        button.OnClick = new Button.ButtonClickedEvent();

        var hudButton = new HudUIButton(obj);
        hudButton._normalSprite = HudUIAssets.ColorButtonSprite;
        hudButton._hoverSprite = HudUIAssets.ColorButtonSelectedSprite;
        hudButton._selectedSprite = HudUIAssets.ColorButtonSelectedSprite;
        hudButton._selectedHoverSprite = HudUIAssets.ColorButtonSelectedSprite;
        hudButton._size = btnSize;

        var normalColor = btnColor;
        var hoverColor = new UnityEngine.Color(
            Mathf.Min(btnColor.r * 1.3f, 1f),
            Mathf.Min(btnColor.g * 1.3f, 1f),
            Mathf.Min(btnColor.b * 1.3f, 1f),
            btnColor.a);

        button.OnMouseOver.AddListener((UnityAction)(() =>
        {
            renderer.sprite = hudButton._hoverSprite;
            renderer.color = hoverColor;
        }));
        button.OnMouseOut.AddListener((UnityAction)(() =>
        {
            renderer.sprite = hudButton._normalSprite;
            renderer.color = normalColor;
        }));

        var localOnClick = onClick;
        button.OnClick.AddListener((UnityAction)(() =>
        {
            try { SoundManager.Instance.PlaySound(LightInDark.UI.Window.VanillaAsset.FindSoundClip("UI_Select"), false, 0.8f); } catch { }
            localOnClick?.Invoke();
        }));

        return hudButton;
    }

    /// <summary>设置选中状态</summary>
    public void SetSelected(bool selected)
    {
        _isSelected = selected;
        Renderer.sprite = selected ? _selectedSprite : _normalSprite;
    }

    /// <summary>设置尺寸</summary>
    public void SetSize(Vector2 size)
    {
        _size = size;
        Renderer.size = size;
        Collider.size = size;
        if (Text != null)
            Text.rectTransform.sizeDelta = size - new Vector2(0.2f, 0.15f);
    }

    /// <summary>设置文本</summary>
    public void SetText(string text)
    {
        if (Text != null)
        {
            Text.text = text;
            Text.ForceMeshUpdate();
        }
    }

    /// <summary>设置可见性</summary>
    public void SetVisible(bool visible) => GameObject.SetActive(visible);

    /// <summary>设置位置</summary>
    public void SetPosition(Vector3 localPos) => GameObject.transform.localPosition = localPos;

    /// <summary>设置颜色</summary>
    public void SetColor(Color color) => Renderer.color = color.ToUnityColor();

    /// <summary>设置点击回调</summary>
    public void SetOnClick(Action onClick)
    {
        Button.OnClick.RemoveAllListeners();
        var localOnClick = onClick;
        Button.OnClick.AddListener((UnityAction)(() =>
        {
            try { SoundManager.Instance.PlaySound(LightInDark.UI.Window.VanillaAsset.FindSoundClip("UI_Select"), false, 0.8f); } catch { }
            localOnClick?.Invoke();
        }));
    }

    /// <summary>销毁</summary>
    public void Destroy() => Object.Destroy(GameObject);

    private static TextMeshPro CreateText(GameObject parent)
    {
        // 尝试使用 VanillaAsset 的 StandardTextPrefab
        try
        {
            var prefab = LightInDark.UI.Window.VanillaAsset.StandardTextPrefab;
            if (prefab != null)
            {
                var tmp = Object.Instantiate(prefab, parent.transform, false);
                tmp.transform.localPosition = Vector3.zero;
                tmp.enableAutoSizing = false;
                tmp.enableWordWrapping = false;
                tmp.raycastTarget = false;
                return tmp;
            }
        }
        catch { }

        // 降级：创建新组件
        var obj = new GameObject("Text");
        obj.layer = LayerMask.NameToLayer("UI");
        obj.transform.SetParent(parent.transform, false);
        obj.transform.localPosition = Vector3.zero;
        var tmp2 = obj.AddComponent<TextMeshPro>();
        var defaultFont = TMP_Settings.defaultFontAsset;
        if (defaultFont != null)
        {
            tmp2.font = defaultFont;
            tmp2.fontSharedMaterial = defaultFont.material;
        }
        tmp2.raycastTarget = false;
        return tmp2;
    }
}

/// <summary>
/// 基于原版 Among Us DialogueBox 克隆的窗口。
/// 使用自定义背景材质（Background_Frame + Background_Inner）。
/// </summary>
public class HudUIWindow
{
    /// <summary>窗口根 GameObject</summary>
    public GameObject GameObject { get; private set; }

    /// <summary>背景 SpriteRenderer</summary>
    public SpriteRenderer BackgroundRenderer { get; private set; }

    /// <summary>内容容器</summary>
    public Transform ContentContainer { get; private set; }

    private readonly List<GameObject> _contentObjects = new();
    private float _currentY = 0f;

    private HudUIWindow(GameObject obj, SpriteRenderer bgRenderer)
    {
        GameObject = obj;
        BackgroundRenderer = bgRenderer;
        ContentContainer = obj.transform;
    }

    /// <summary>
    /// 创建窗口（使用自定义背景材质）
    /// </summary>
    /// <param name="title">标题（仅用于命名）</param>
    /// <param name="size">窗口大小</param>
    /// <param name="parent">父级 Transform</param>
    public static HudUIWindow Create(string title = "", Vector2? size = null, Transform? parent = null)
    {
        parent ??= HudManager.Instance?.transform;
        if (parent == null) throw new InvalidOperationException("HudManager 未就绪");

        var windowSize = size ?? new Vector2(5f, 3f);

        var obj = new GameObject($"HudUIWindow_{title}");
        obj.layer = LayerMask.NameToLayer("UI");
        obj.transform.SetParent(parent, false);
        obj.transform.localPosition = new Vector3(0f, 0f, -50f);
        obj.transform.localScale = Vector3.one;

        // 黑色遮罩
        var blackObj = new GameObject("BlackScreen");
        blackObj.layer = LayerMask.NameToLayer("UI");
        blackObj.transform.SetParent(obj.transform, false);
        blackObj.transform.localPosition = new Vector3(0f, 0f, 1f);
        var blackRenderer = blackObj.AddComponent<SpriteRenderer>();
        blackRenderer.sprite = LightInDark.UI.Window.VanillaAsset.FullScreenSprite;
        blackRenderer.drawMode = SpriteDrawMode.Sliced;
        blackRenderer.size = new Vector2(30f, 30f);
        blackRenderer.color = new UnityEngine.Color(0f, 0f, 0f, 0.35f);
        blackRenderer.sortingOrder = 50;

        // 窗口外框（Background_Frame）
        var frameObj = new GameObject("Frame");
        frameObj.layer = LayerMask.NameToLayer("UI");
        frameObj.transform.SetParent(obj.transform, false);
        frameObj.transform.localPosition = Vector3.zero;
        var frameRenderer = frameObj.AddComponent<SpriteRenderer>();
        frameRenderer.sprite = HudUIAssets.FrameSprite;
        frameRenderer.drawMode = SpriteDrawMode.Sliced;
        frameRenderer.tileMode = SpriteTileMode.Continuous;
        frameRenderer.size = windowSize;
        frameRenderer.color = UnityEngine.Color.white;
        frameRenderer.sortingOrder = 51;

        // 窗口内框（Background_Inner）
        var innerObj = new GameObject("Inner");
        innerObj.layer = LayerMask.NameToLayer("UI");
        innerObj.transform.SetParent(frameObj.transform, false);
        innerObj.transform.localPosition = new Vector3(0f, 0f, -0.1f);
        var innerRenderer = innerObj.AddComponent<SpriteRenderer>();
        innerRenderer.sprite = HudUIAssets.InnerSprite;
        innerRenderer.drawMode = SpriteDrawMode.Sliced;
        innerRenderer.tileMode = SpriteTileMode.Continuous;
        innerRenderer.size = windowSize - new Vector2(0.3f, 0.3f);
        innerRenderer.color = new UnityEngine.Color(0.15f, 0.15f, 0.15f, 0.95f);
        innerRenderer.sortingOrder = 51;

        // 内容容器
        var contentObj = new GameObject("Content");
        contentObj.layer = LayerMask.NameToLayer("UI");
        contentObj.transform.SetParent(obj.transform, false);
        contentObj.transform.localPosition = new Vector3(0f, windowSize.y * 0.4f, -1f);

        var window = new HudUIWindow(obj, frameRenderer);

        // 关闭按钮
        var closeBtn = CreateCloseButton(obj.transform,
            new Vector3(windowSize.x * 0.5f - 0.2f, windowSize.y * 0.5f - 0.2f, -2f),
            () => window.Close());
        window._contentObjects.Add(closeBtn);

        return window;
    }

    /// <summary>
    /// 关闭并销毁窗口
    /// </summary>
    public void Close()
    {
        ClearContent();
        Object.Destroy(GameObject);
    }

    /// <summary>清空内容</summary>
    public void ClearContent()
    {
        foreach (var obj in _contentObjects)
        {
            if (obj != null) Object.Destroy(obj);
        }
        _contentObjects.Clear();
        _currentY = 0f;
    }

    /// <summary>添加文本</summary>
    public TextMeshPro AddText(string text, float fontSize = 2f,
        TextAlignmentOptions alignment = TextAlignmentOptions.Center)
    {
        var obj = new GameObject("Text");
        obj.layer = LayerMask.NameToLayer("UI");
        obj.transform.SetParent(ContentContainer, false);
        obj.transform.localPosition = new Vector3(0f, _currentY, -1f);

        var tmp = CreateTextMeshPro(obj);
        tmp.text = text;
        tmp.fontSize = fontSize;
        tmp.fontSizeMax = fontSize;
        tmp.fontSizeMin = fontSize * 0.5f;
        tmp.alignment = alignment;
        tmp.color = UnityEngine.Color.white;
        tmp.ForceMeshUpdate();
        tmp.rectTransform.sizeDelta = new Vector2(4.5f, tmp.preferredHeight + 0.1f);
        tmp.rectTransform.pivot = new Vector2(0.5f, 0.5f);

        _currentY -= tmp.preferredHeight + 0.2f;
        _contentObjects.Add(obj);
        return tmp;
    }

    /// <summary>添加现代风格按钮</summary>
    public HudUIButton AddButton(string text, Action onClick, Vector2? size = null, Color? color = null)
    {
        var btn = HudUIButton.Create(ContentContainer, text, size ?? ButtonSize.Rectangle,
            () => { onClick?.Invoke(); });

        btn.SetPosition(new Vector3(0f, _currentY, -1f));

        var btnHeight = (size ?? ButtonSize.Rectangle).y;
        _currentY -= btnHeight + 0.15f;

        if (color != null) btn.SetColor(color.Value);

        _contentObjects.Add(btn.GameObject);
        return btn;
    }

    /// <summary>添加颜色按钮</summary>
    public HudUIButton AddColorButton(string text, Action onClick, Vector2? size = null, Color? color = null)
    {
        var btn = HudUIButton.CreateColorButton(ContentContainer, text, size ?? ButtonSize.Rectangle,
            () => { onClick?.Invoke(); }, color);

        btn.SetPosition(new Vector3(0f, _currentY, -1f));

        var btnHeight = (size ?? ButtonSize.Rectangle).y;
        _currentY -= btnHeight + 0.15f;

        _contentObjects.Add(btn.GameObject);
        return btn;
    }

    /// <summary>添加留白</summary>
    public void AddMargin(float height)
    {
        _currentY -= height;
    }

    private static GameObject CreateCloseButton(Transform parent, Vector3 localPos, Action onClose)
    {
        var obj = new GameObject("CloseButton");
        obj.layer = LayerMask.NameToLayer("UI");
        obj.transform.SetParent(parent, false);
        obj.transform.localPosition = localPos;
        obj.transform.localScale = Vector3.one;

        var renderer = obj.AddComponent<SpriteRenderer>();
        renderer.sprite = HudUIAssets.CloseNormal;
        renderer.drawMode = SpriteDrawMode.Sliced;
        renderer.size = new Vector2(0.4f, 0.4f);
        renderer.sortingOrder = 53;

        var collider = obj.AddComponent<BoxCollider2D>();
        collider.size = new Vector2(0.4f, 0.4f);
        collider.isTrigger = true;

        var button = obj.AddComponent<PassiveButton>();
        button.OnMouseOver = new UnityEvent();
        button.OnMouseOut = new UnityEvent();
        button.OnClick = new Button.ButtonClickedEvent();

        button.OnMouseOver.AddListener((UnityAction)(() => { renderer.sprite = HudUIAssets.CloseHover; }));
        button.OnMouseOut.AddListener((UnityAction)(() => { renderer.sprite = HudUIAssets.CloseNormal; }));

        var localOnClose = onClose;
        button.OnClick.AddListener((UnityAction)(() => { localOnClose?.Invoke(); }));

        return obj;
    }

    private static TextMeshPro CreateTextMeshPro(GameObject parent)
    {
        try
        {
            var prefab = LightInDark.UI.Window.VanillaAsset.StandardTextPrefab;
            if (prefab != null)
            {
                var tmp = Object.Instantiate(prefab, parent.transform, false);
                tmp.transform.localPosition = Vector3.zero;
                tmp.enableAutoSizing = false;
                tmp.enableWordWrapping = false;
                tmp.raycastTarget = false;
                return tmp;
            }
        }
        catch { }

        var obj = new GameObject("Text");
        obj.layer = LayerMask.NameToLayer("UI");
        obj.transform.SetParent(parent.transform, false);
        obj.transform.localPosition = Vector3.zero;
        var tmp2 = obj.AddComponent<TextMeshPro>();
        var defaultFont = TMP_Settings.defaultFontAsset;
        if (defaultFont != null)
        {
            tmp2.font = defaultFont;
            tmp2.fontSharedMaterial = defaultFont.material;
        }
        tmp2.raycastTarget = false;
        return tmp2;
    }
}

using System;
using TMPro;
using UnityEngine;

namespace LightInDark.UI.HudUI;

/// <summary>
/// HudUI 高级辅助方法。
/// 基于自定义精灵图材质实现窗口和按钮。
/// </summary>
public static class HudUI
{
    /// <summary>
    /// 按钮窗口选项
    /// </summary>
    public readonly struct ButtonOption
    {
        public readonly string Label;
        public readonly Action OnClick;
        public readonly Color? Color;
        public readonly Vector2? Size;

        public ButtonOption(string label, Action onClick, Color? color = null, Vector2? size = null)
        {
            Label = label;
            OnClick = onClick;
            Color = color;
            Size = size;
        }
    }

    /// <summary>
    /// 打开一个按钮选择窗口
    /// </summary>
    public static HudUIWindow OpenButtonWindow(string title, params ButtonOption[] options)
    {
        var window = HudUIWindow.Create(title, new Vector2(4.5f, 1f + options.Length * 0.65f));

        // 标题
        window.AddText(title, 2.2f, TextAlignmentOptions.Center);
        window.AddMargin(0.2f);

        // 按钮
        foreach (var opt in options)
        {
            var localOpt = opt;
            window.AddButton(localOpt.Label, () =>
            {
                localOpt.OnClick?.Invoke();
                window.Close();
            }, localOpt.Size ?? ButtonSize.Rectangle, localOpt.Color);
        }

        return window;
    }

    /// <summary>
    /// 打开一个确认对话框（是/否）
    /// </summary>
    public static HudUIWindow OpenConfirmDialog(string message, Action onConfirm, Action? onCancel = null)
    {
        var window = HudUIWindow.Create("", new Vector2(3.9f, 2f));

        window.AddText(message, 1.5f, TextAlignmentOptions.Center);
        window.AddMargin(0.2f);

        var localOnConfirm = onConfirm;
        var localOnCancel = onCancel;

        // "是" 按钮
        var yesBtn = window.AddButton("是", () =>
        {
            localOnConfirm?.Invoke();
            window.Close();
        }, ButtonSize.Rectangle, Color.Green);

        // "否" 按钮
        var noBtn = window.AddButton("否", () =>
        {
            localOnCancel?.Invoke();
            window.Close();
        }, ButtonSize.Rectangle, Color.Red);

        return window;
    }

    /// <summary>
    /// 打开一个消息对话框（仅含"确定"按钮）
    /// </summary>
    public static HudUIWindow OpenMessageDialog(string message, Action? onClose = null)
    {
        var window = HudUIWindow.Create("", new Vector2(3.5f, 1.8f));

        window.AddText(message, 1.5f, TextAlignmentOptions.Center);
        window.AddMargin(0.2f);

        var localOnClose = onClose;
        window.AddButton("确定", () =>
        {
            localOnClose?.Invoke();
            window.Close();
        }, ButtonSize.Rectangle);

        return window;
    }

    /// <summary>
    /// 打开一个文本展示窗口（带标题）
    /// </summary>
    public static HudUIWindow OpenTextWindow(string title, string text)
    {
        var window = HudUIWindow.Create(title, new Vector2(5f, 3.5f));

        window.AddText(title, 2.2f, TextAlignmentOptions.Center);
        window.AddMargin(0.2f);
        window.AddText(text, 1.2f, TextAlignmentOptions.Left);

        return window;
    }

    /// <summary>
    /// 打开一个自定义内容窗口
    /// </summary>
    public static HudUIWindow OpenCustomWindow(string title, Action<HudUIWindow> builder, Vector2? windowSize = null)
    {
        var window = HudUIWindow.Create(title, windowSize ?? new Vector2(5f, 3f));

        if (!string.IsNullOrEmpty(title))
        {
            window.AddText(title, 2.2f, TextAlignmentOptions.Center);
            window.AddMargin(0.2f);
        }

        builder?.Invoke(window);
        return window;
    }
}

